import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Session, SupabaseClient } from '@supabase/supabase-js';
import Sidebar from './components/Sidebar';
import Header from './components/Header';
import AnalyticsDashboard from './components/AnalyticsDashboard';
import Projects from './components/Projects';
import Milestones from './components/Milestones';
import Team from './components/Team';
import Payments from './components/Payments';
import MaintenanceContracts from './components/MaintenanceContracts';
import SystemManagement from './components/SystemManagement';
import MilestoneFilter from './components/MilestoneFilter';
import ReportsBuilder from './components/ReportsBuilder';
import Login from './components/Login';
import EditProjectModal from './components/EditProjectModal';
import EditMilestoneModal from './components/EditMilestoneModal';
import MilestoneDetailModal from './components/MilestoneDetailModal';
import ConfirmDeleteModal from './components/ConfirmDeleteModal';
import Chatbot from './components/Chatbot';
import { Language, Theme, View, Project, Milestone, User, Lookups } from './types';
import { fetchAllData, addProject as apiAddProject, updateProject as apiUpdateProject, addMilestones as apiAddMilestones, updateMilestone as apiUpdateMilestone, updateLookups as apiUpdateLookups, deleteProject as apiDeleteProject } from './services/api';
import { initSupabase } from './services/supabaseClient';

const App: React.FC = () => {
    const [view, setView] = useState<View>(() => (localStorage.getItem('lastView') as View) || 'dashboard');
    const [language, setLanguage] = useState<Language>(() => (localStorage.getItem('language') as Language) || 'en');
    const [theme, setTheme] = useState<Theme>(() => (localStorage.getItem('theme') as Theme) || 'light');
    const [isLoading, setIsLoading] = useState(true);
    const [errorMsg, setErrorMsg] = useState<string | null>(null);

    const [projects, setProjects] = useState<Project[]>([]);
    const [milestones, setMilestones] = useState<Milestone[]>([]);
    const [users, setUsers] = useState<User[]>([]);
    const [lookups, setLookups] = useState<Lookups>({ countries: [], categories: [], teams: [], products: [], projectStatuses: [], projectManagers: [], customers: [] });

    const [editingProject, setEditingProject] = useState<Project | null>(null);
    const [editingMilestone, setEditingMilestone] = useState<Milestone | null>(null);
    const [viewingMilestone, setViewingMilestone] = useState<Milestone | null>(null);
    const [deletingProject, setDeletingProject] = useState<Project | null>(null);
    const [isChatbotOpen, setIsChatbotOpen] = useState(false);
    const [isImportModalOpen, setIsImportModalOpen] = useState(false);

    const [session, setSession] = useState<Session | null>(null);
    const [supabaseClient, setSupabaseClient] = useState<SupabaseClient | null>(null);
    const [isAppConfigured, setIsAppConfigured] = useState(false);

    const isFetching = useRef(false);

    useEffect(() => { localStorage.setItem('lastView', view); }, [view]);
    useEffect(() => { localStorage.setItem('language', language); }, [language]);
    useEffect(() => {
        localStorage.setItem('theme', theme);
        document.documentElement.classList.toggle('dark', theme === 'dark' || (theme === 'system' && window.matchMedia('(prefers-color-scheme: dark)').matches));
    }, [theme]);

    const setupClient = useCallback((key: string, url: string) => {
        try {
            const client = initSupabase(url, key);
            setSupabaseClient(client);
            setIsAppConfigured(true);
            setErrorMsg(null);
            return true;
        } catch (e: any) {
            setErrorMsg(e.message || "Invalid Supabase Configuration");
            setIsAppConfigured(false);
            return false;
        }
    }, []);

    useEffect(() => {
        const key = localStorage.getItem('supabaseAnonKey');
        const url = localStorage.getItem('supabaseUrl') || 'https://dcamlinhazzmbaldsrdo.supabase.co';
        if (key?.trim()) {
            setupClient(key, url);
        } else {
            setIsAppConfigured(false);
            setIsLoading(false);
        }
    }, [setupClient]);

    useEffect(() => {
        if (!supabaseClient) return;
        supabaseClient.auth.getSession().then(({ data: { session } }) => {
            setSession(session);
            setIsLoading(false);
        });
        const { data: { subscription } } = supabaseClient.auth.onAuthStateChange((_event, session) => {
            setSession(session);
        });
        return () => subscription.unsubscribe();
    }, [supabaseClient]);

    const loadData = useCallback(async () => {
        if (!session || isFetching.current) return;
        try {
            isFetching.current = true;
            const data = await fetchAllData();
            setProjects(data.projects || []);
            setMilestones(data.milestones || []);
            setUsers(data.users || []);
            if (data.lookups) setLookups(data.lookups);
            setErrorMsg(null);
        } catch (e: any) {
            setErrorMsg("Connection error: Make sure your tables exist in Supabase.");
        } finally {
            isFetching.current = false;
        }
    }, [session]);

    useEffect(() => {
        if (session) loadData();
    }, [session, loadData]);

    const handleSaveConfig = (key: string, url: string) => {
        localStorage.setItem('supabaseAnonKey', key);
        localStorage.setItem('supabaseUrl', url);
        if (setupClient(key, url)) {
            // Success
        }
    };

    if (isLoading) return <div className="min-h-screen bg-white dark:bg-slate-950 flex items-center justify-center flex-col gap-4"><div className="w-10 h-10 border-4 border-slate-200 border-t-violet-600 rounded-full animate-spin"></div></div>;
    if (!isAppConfigured) return <SystemManagement lookups={lookups} onUpdate={() => {}} language={language} onSaveConfig={handleSaveConfig} isSetupMode={true} />;
    if (!session) return <Login onLoginSuccess={() => loadData()} language={language} setLanguage={setLanguage} supabaseClient={supabaseClient!} />;

    return (
        <div className="flex h-screen bg-slate-50 dark:bg-slate-950 transition-colors duration-300 overflow-hidden" dir={language === 'ar' ? 'rtl' : 'ltr'}>
            <Sidebar currentView={view} setCurrentView={setView} language={language} />
            <div className="flex-1 flex flex-col min-w-0 overflow-hidden">
                <Header user={users.find(u => u.id === session.user.id)} language={language} setLanguage={setLanguage} onSearch={() => {}} onLogout={() => supabaseClient?.auth.signOut()} theme={theme} setTheme={setTheme} isDbConnected={!!session} />
                {errorMsg && (
                    <div className="mx-8 mt-4 p-3 bg-red-50 dark:bg-red-900/20 border border-red-200 rounded-xl flex justify-between items-center animate-in slide-in-from-top-1">
                        <p className="text-[10px] font-black uppercase text-red-600">{errorMsg}</p>
                        <button onClick={() => { localStorage.clear(); window.location.reload(); }} className="text-[9px] font-black bg-red-600 text-white px-3 py-1 rounded-lg">RESET</button>
                    </div>
                )}
                <main className="flex-1 overflow-y-auto p-8 custom-scrollbar">
                    {view === 'dashboard' && <AnalyticsDashboard projects={projects} milestones={milestones} projectManagers={lookups.projectManagers} language={language} />}
                    {view === 'projects' && <Projects allProjects={projects} allUsers={users} language={language} onAddProject={async (d) => { await apiAddProject(d); loadData(); }} onOpenEditModal={setEditingProject} onOpenDeleteModal={setDeletingProject} lookups={lookups} isImportModalOpen={isImportModalOpen} onOpenImportModal={() => setIsImportModalOpen(true)} onCloseImportModal={() => setIsImportModalOpen(false)} onImportProjects={async () => {}} />}
                    {view === 'milestones' && <Milestones allMilestones={milestones} allProjects={projects} language={language} onAddMilestones={async (d) => { await apiAddMilestones(d); loadData(); }} onOpenEditModal={setEditingMilestone} onViewMilestoneDetails={setViewingMilestone} onUpdateMilestone={async (id, d) => { await apiUpdateMilestone(id, d); loadData(); }} lookups={lookups} />}
                    {view === 'team' && <Team allUsers={users} allProjects={projects} language={language} />}
                    {view === 'payments' && <Payments allProjects={projects} allMilestones={milestones} allTeams={lookups.teams} language={language} onUpdateMilestone={async (id, d) => { await apiUpdateMilestone(id, d); loadData(); }} />}
                    {view === 'system' && <SystemManagement lookups={lookups} onUpdate={apiUpdateLookups} language={language} onSaveConfig={handleSaveConfig} />}
                    {view === 'filter' && <MilestoneFilter projects={projects} milestones={milestones} teams={lookups.teams} customers={lookups.customers} projectManagers={lookups.projectManagers} language={language} onUpdateMilestone={async (id, d) => { await apiUpdateMilestone(id, d); loadData(); }} />}
                    {view === 'reports' && <ReportsBuilder projects={projects} milestones={milestones} language={language} />}
                </main>
            </div>
            {editingProject && <EditProjectModal projectToEdit={editingProject} lookups={lookups} onClose={() => setEditingProject(null)} onUpdateProject={async (id, d) => { await apiUpdateProject(id, d); loadData(); }} language={language} />}
            {editingMilestone && <EditMilestoneModal milestoneToEdit={editingMilestone} allMilestones={milestones} teams={lookups.teams} projects={projects} allMilestoneUpdates={[]} allUsers={users} currentUser={users.find(u => u.id === session.user.id)} onClose={() => setEditingMilestone(null)} onUpdateMilestone={async (id, d) => { await apiUpdateMilestone(id, d); loadData(); }} onAddMilestones={async (d) => { await apiAddMilestones(d); loadData(); }} onAddUpdate={async () => {}} language={language} />}
            {viewingMilestone && <MilestoneDetailModal milestone={viewingMilestone} projects={projects} allMilestoneUpdates={[]} allUsers={users} lookups={lookups} onClose={() => setViewingMilestone(null)} language={language} />}
            {deletingProject && <ConfirmDeleteModal project={deletingProject} onClose={() => setDeletingProject(null)} onConfirm={async () => { await apiDeleteProject(deletingProject.id); setDeletingProject(null); loadData(); }} language={language} />}
            <button onClick={() => setIsChatbotOpen(true)} className="fixed bottom-8 right-8 rtl:left-8 rtl:right-auto bg-slate-900 text-white p-4 rounded-full shadow-xl hover:scale-110 active:scale-95 transition-all z-50"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" viewBox="0 0 20 20" fill="currentColor"><path d="M2 5a2 2 0 012-2h7a2 2 0 012 2v4a2 2 0 01-2 2H9l-3 3v-3H4a2 2 0 01-2-2V5z" /></svg></button>
            <Chatbot isOpen={isChatbotOpen} onClose={() => setIsChatbotOpen(false)} language={language} projects={projects} milestones={milestones} users={users} lookups={lookups} />
        </div>
    );
};

export default App;

import React, { useState, useMemo } from 'react';
import { Project, Milestone, Language } from '../types';

interface Field {
    id: string;
    label: string;
    category: 'Project' | 'Milestone';
    accessor: (proj: Project, mile?: Milestone) => string | number | null;
}

const AVAILABLE_FIELDS: Field[] = [
    { id: 'proj_name', label: 'Project Name / اسم المشروع', category: 'Project', accessor: (p) => p.name },
    { id: 'proj_code', label: 'Project Code / كود المشروع', category: 'Project', accessor: (p) => p.projectCode },
    { id: 'proj_pm', label: 'Project Manager / مدير المشروع', category: 'Project', accessor: (p) => p.projectManager?.name || '--' },
    { id: 'proj_customer', label: 'Customer / العميل', category: 'Project', accessor: (p) => p.customer?.name || '--' },
    { id: 'proj_status', label: 'Project Status / حالة المشروع', category: 'Project', accessor: (p) => p.status?.name || '--' },
    { id: 'proj_progress', label: 'Progress / التقدم', category: 'Project', accessor: (p) => `${p.progress}%` },
    { id: 'mile_title', label: 'Milestone Title / اسم الدفعة', category: 'Milestone', accessor: (_, m) => m?.title || '--' },
    { id: 'mile_amount', label: 'Amount / قيمة الدفعة', category: 'Milestone', accessor: (_, m) => m?.hasPayment ? m.paymentAmount : '--' },
    { id: 'mile_pay_status', label: 'Payment Status / حالة الدفعة', category: 'Milestone', accessor: (_, m) => m?.paymentStatus || '--' },
    { id: 'mile_due', label: 'Due Date / تاريخ الاستحقاق', category: 'Milestone', accessor: (_, m) => m?.dueDate ? new Date(m.dueDate).toLocaleDateString() : '--' },
    { id: 'mile_status', label: 'Milestone Status / حالة المعلم', category: 'Milestone', accessor: (_, m) => m?.status || '--' },
    { id: 'proj_country', label: 'Country / البلد', category: 'Project', accessor: (p) => p.country?.name || '--' },
];

interface ReportsBuilderProps {
    projects: Project[];
    milestones: Milestone[];
    language: Language;
}

const ReportsBuilder: React.FC<ReportsBuilderProps> = ({ projects, milestones, language }) => {
    const [selectedFields, setSelectedFields] = useState<Field[]>([]);
    const [draggedField, setDraggedField] = useState<Field | null>(null);
    const [searchTerm, setSearchTerm] = useState('');

    const translations = {
        ar: {
            title: "بناء التقارير المخصصة",
            subtitle: "قم بسحب الحقول وتنسيقها لإنشاء تقريرك الخاص.",
            availableFields: "الحقول المتاحة",
            dropZone: "اسحب الحقول هنا لتشكيل أعمدة التقرير",
            preview: "معاينة التقرير",
            export: "تصدير للتقرير",
            searchPlaceholder: "بحث عن حقل...",
            clear: "مسح الكل",
            noFields: "لم يتم اختيار حقول بعد.",
        },
        en: {
            title: "Custom Report Builder",
            subtitle: "Drag and drop fields to design your custom report layout.",
            availableFields: "Available Fields",
            dropZone: "Drop fields here to form report columns",
            preview: "Report Preview",
            export: "Export Report",
            searchPlaceholder: "Search fields...",
            clear: "Clear All",
            noFields: "No fields selected yet.",
        }
    };
    const t = translations[language];

    const filteredAvailableFields = AVAILABLE_FIELDS.filter(f => 
        !selectedFields.find(sf => sf.id === f.id) && 
        f.label.toLowerCase().includes(searchTerm.toLowerCase())
    );

    const handleDragStart = (field: Field) => {
        setDraggedField(field);
    };

    const handleDrop = (e: React.DragEvent) => {
        e.preventDefault();
        if (draggedField && !selectedFields.find(f => f.id === draggedField.id)) {
            setSelectedFields([...selectedFields, draggedField]);
            setDraggedField(null);
        }
    };

    const removeField = (fieldId: string) => {
        setSelectedFields(selectedFields.filter(f => f.id !== fieldId));
    };

    const reportData = useMemo(() => {
        const rows: any[] = [];
        projects.forEach(p => {
            const pMilestones = milestones.filter(m => m.projectId === p.id);
            if (pMilestones.length > 0) {
                pMilestones.forEach(m => {
                    const row: any = {};
                    selectedFields.forEach(f => {
                        row[f.id] = f.accessor(p, m);
                    });
                    rows.push(row);
                });
            } else {
                const row: any = {};
                selectedFields.forEach(f => {
                    row[f.id] = f.accessor(p);
                });
                rows.push(row);
            }
        });
        return rows;
    }, [projects, milestones, selectedFields]);

    const handleExport = () => {
        if (selectedFields.length === 0) return;
        const headers = selectedFields.map(f => f.label).join(',');
        const rows = reportData.map(row => 
            selectedFields.map(f => `"${String(row[f.id] || '').replace(/"/g, '""')}"`).join(',')
        ).join('\n');

        const csvContent = "\uFEFF" + headers + '\n' + rows;
        const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
        const link = document.createElement('a');
        link.href = URL.createObjectURL(blob);
        link.setAttribute('download', `PioTech_Custom_Report_${new Date().toISOString().slice(0,10)}.csv`);
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
    };

    return (
        <div className="space-y-8 max-w-[1600px] mx-auto pb-20">
            <div className="flex justify-between items-end">
                <div>
                    <h1 className="text-3xl font-black text-slate-800 dark:text-white uppercase tracking-tight">{t.title}</h1>
                    <p className="text-slate-400 font-bold text-[10px] mt-2 uppercase tracking-widest">{t.subtitle}</p>
                </div>
                <div className="flex gap-3">
                    <button onClick={() => setSelectedFields([])} className="px-6 py-2.5 text-[10px] font-black text-slate-400 border border-slate-200 dark:border-slate-800 rounded-xl hover:bg-slate-50 uppercase tracking-widest">{t.clear}</button>
                    <button onClick={handleExport} disabled={selectedFields.length === 0} className="px-8 py-2.5 text-[10px] font-black text-white bg-violet-600 rounded-xl hover:bg-violet-700 transition-all uppercase tracking-widest shadow-xl shadow-violet-500/20 disabled:opacity-50">{t.export}</button>
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
                {/* Available Fields - Draggable Items */}
                <div className="lg:col-span-3 space-y-4">
                    <div className="bg-white dark:bg-slate-900 border border-slate-100 dark:border-slate-800 p-6 rounded-[2.5rem] shadow-sm flex flex-col h-[600px]">
                        <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-4">{t.availableFields}</h2>
                        <div className="relative mb-6">
                            <input 
                                type="text" 
                                value={searchTerm}
                                onChange={(e) => setSearchTerm(e.target.value)}
                                placeholder={t.searchPlaceholder} 
                                className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-700 p-3 rounded-2xl text-xs outline-none focus:ring-1 focus:ring-violet-500" 
                            />
                        </div>
                        <div className="flex-1 overflow-y-auto custom-scrollbar space-y-2 pe-2">
                            {filteredAvailableFields.map(field => (
                                <div
                                    key={field.id}
                                    draggable
                                    onDragStart={() => handleDragStart(field)}
                                    className="p-4 bg-slate-50 dark:bg-slate-800/50 border border-slate-100 dark:border-slate-800 rounded-2xl cursor-grab active:cursor-grabbing hover:border-violet-300 dark:hover:border-violet-700 group transition-all"
                                >
                                    <div className="flex items-center gap-3">
                                        <div className="w-8 h-8 rounded-lg bg-white dark:bg-slate-900 flex items-center justify-center shadow-sm group-hover:text-violet-600">
                                            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M4 6h16M4 12h16M4 18h16" /></svg>
                                        </div>
                                        <div>
                                            <p className="text-[10px] font-black text-slate-800 dark:text-white truncate">{field.label.split('/')[language === 'ar' ? 1 : 0]}</p>
                                            <p className="text-[8px] font-bold text-slate-400 uppercase tracking-widest">{field.category}</p>
                                        </div>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>

                {/* Drop Zone & Preview */}
                <div className="lg:col-span-9 space-y-8">
                    {/* Columns Selector */}
                    <div 
                        onDragOver={(e) => e.preventDefault()}
                        onDrop={handleDrop}
                        className="bg-slate-50 dark:bg-slate-900/40 border-2 border-dashed border-slate-200 dark:border-slate-800 p-8 rounded-[3rem] min-h-[160px] flex flex-wrap gap-3 items-center justify-center transition-colors hover:bg-slate-100/50 dark:hover:bg-slate-800/20"
                    >
                        {selectedFields.length === 0 ? (
                            <div className="text-center opacity-30">
                                <svg className="w-12 h-12 mx-auto mb-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="1.5" d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" /></svg>
                                <p className="text-xs font-black uppercase tracking-widest">{t.dropZone}</p>
                            </div>
                        ) : (
                            selectedFields.map(field => (
                                <div key={field.id} className="bg-white dark:bg-slate-800 border border-slate-100 dark:border-slate-700 px-5 py-3 rounded-2xl shadow-sm flex items-center gap-4 animate-in zoom-in-95">
                                    <span className="text-[11px] font-black text-slate-700 dark:text-slate-200">{field.label.split('/')[language === 'ar' ? 1 : 0]}</span>
                                    <button onClick={() => removeField(field.id)} className="text-slate-300 hover:text-red-500 transition-colors">
                                        <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M6 18L18 6M6 6l12 12" /></svg>
                                    </button>
                                </div>
                            ))
                        )}
                    </div>

                    {/* Preview Table */}
                    <div className="bg-white dark:bg-slate-900 border border-slate-100 dark:border-slate-800 rounded-[2.5rem] shadow-sm overflow-hidden flex flex-col h-[400px]">
                        <div className="p-6 border-b border-slate-50 dark:border-slate-800 flex justify-between items-center">
                            <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">{t.preview}</h2>
                            <span className="text-[10px] font-black text-violet-500 uppercase tracking-widest">{reportData.length} Rows</span>
                        </div>
                        <div className="flex-1 overflow-auto custom-scrollbar">
                            <table className="w-full text-start border-collapse">
                                <thead className="sticky top-0 bg-slate-50 dark:bg-slate-800/80 backdrop-blur-md">
                                    <tr>
                                        {selectedFields.map(f => (
                                            <th key={f.id} className="px-6 py-4 text-[9px] font-black text-slate-400 uppercase tracking-widest text-start whitespace-nowrap border-b border-slate-100 dark:border-slate-800">{f.label.split('/')[language === 'ar' ? 1 : 0]}</th>
                                        ))}
                                        {selectedFields.length === 0 && <th className="px-6 py-10 text-center text-[10px] font-bold text-slate-300 uppercase tracking-widest italic">{t.noFields}</th>}
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-slate-50 dark:divide-slate-800">
                                    {reportData.slice(0, 15).map((row, idx) => (
                                        <tr key={idx} className="hover:bg-slate-50 dark:hover:bg-slate-800/30 transition-colors">
                                            {selectedFields.map(f => (
                                                <td key={f.id} className="px-6 py-4 text-[11px] font-bold text-slate-600 dark:text-slate-300 whitespace-nowrap">{row[f.id]}</td>
                                            ))}
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default ReportsBuilder;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Session, SupabaseClient } from '@supabase/supabase-js';
import Sidebar from './components/Sidebar';
import Header from './components/Header';
import AnalyticsDashboard from './components/AnalyticsDashboard';
import Projects from './components/Projects';
import Milestones from './components/Milestones';
import Team from './components/Team';
import Payments from './components/Payments';
import MaintenanceContracts from './components/MaintenanceContracts';
import SystemManagement from './components/SystemManagement';
import MilestoneFilter from './components/MilestoneFilter';
import ReportsBuilder from './components/ReportsBuilder';
import Login from './components/Login';
import EditProjectModal from './components/EditProjectModal';
import EditMilestoneModal from './components/EditMilestoneModal';
import MilestoneDetailModal from './components/MilestoneDetailModal';
import ConfirmDeleteModal from './components/ConfirmDeleteModal';
import Chatbot from './components/Chatbot';
import { Language, Theme, View, Project, Milestone, User, Lookups } from './types';
import { fetchAllData, addProject as apiAddProject, updateProject as apiUpdateProject, addMilestones as apiAddMilestones, updateMilestone as apiUpdateMilestone, updateLookups as apiUpdateLookups, deleteProject as apiDeleteProject } from './services/api';
import { initSupabase } from './services/supabaseClient';

const App: React.FC = () => {
    const [view, setView] = useState<View>(() => (localStorage.getItem('lastView') as View) || 'dashboard');
    const [language, setLanguage] = useState<Language>(() => (localStorage.getItem('language') as Language) || 'en');
    const [theme, setTheme] = useState<Theme>(() => (localStorage.getItem('theme') as Theme) || 'light');
    const [isLoading, setIsLoading] = useState(true);
    const [errorMsg, setErrorMsg] = useState<string | null>(null);

    const [projects, setProjects] = useState<Project[]>([]);
    const [milestones, setMilestones] = useState<Milestone[]>([]);
    const [users, setUsers] = useState<User[]>([]);
    const [lookups, setLookups] = useState<Lookups>({ countries: [], categories: [], teams: [], products: [], projectStatuses: [], projectManagers: [], customers: [] });

    const [editingProject, setEditingProject] = useState<Project | null>(null);
    const [editingMilestone, setEditingMilestone] = useState<Milestone | null>(null);
    const [viewingMilestone, setViewingMilestone] = useState<Milestone | null>(null);
    const [deletingProject, setDeletingProject] = useState<Project | null>(null);
    const [isChatbotOpen, setIsChatbotOpen] = useState(false);
    const [isImportModalOpen, setIsImportModalOpen] = useState(false);

    const [session, setSession] = useState<Session | null>(null);
    const [supabaseClient, setSupabaseClient] = useState<SupabaseClient | null>(null);
    const [isAppConfigured, setIsAppConfigured] = useState(false);

    const isFetching = useRef(false);

    useEffect(() => { localStorage.setItem('lastView', view); }, [view]);
    useEffect(() => { localStorage.setItem('language', language); }, [language]);
    useEffect(() => {
        localStorage.setItem('theme', theme);
        document.documentElement.classList.toggle('dark', theme === 'dark' || (theme === 'system' && window.matchMedia('(prefers-color-scheme: dark)').matches));
    }, [theme]);

    const setupClient = useCallback((key: string, url: string) => {
        try {
            const client = initSupabase(url, key);
            setSupabaseClient(client);
            setIsAppConfigured(true);
            setErrorMsg(null);
            return true;
        } catch (e: any) {
            setErrorMsg(e.message || "Invalid Supabase Configuration");
            setIsAppConfigured(false);
            return false;
        }
    }, []);

    useEffect(() => {
        const key = localStorage.getItem('supabaseAnonKey');
        const url = localStorage.getItem('supabaseUrl') || 'https://dcamlinhazzmbaldsrdo.supabase.co';
        if (key?.trim()) {
            setupClient(key, url);
        } else {
            setIsAppConfigured(false);
            setIsLoading(false);
        }
    }, [setupClient]);

    useEffect(() => {
        if (!supabaseClient) return;
        supabaseClient.auth.getSession().then(({ data: { session } }) => {
            setSession(session);
            setIsLoading(false);
        });
        const { data: { subscription } } = supabaseClient.auth.onAuthStateChange((_event, session) => {
            setSession(session);
        });
        return () => subscription.unsubscribe();
    }, [supabaseClient]);

    const loadData = useCallback(async () => {
        if (!session || isFetching.current) return;
        try {
            isFetching.current = true;
            const data = await fetchAllData();
            setProjects(data.projects || []);
            setMilestones(data.milestones || []);
            setUsers(data.users || []);
            if (data.lookups) setLookups(data.lookups);
            setErrorMsg(null);
        } catch (e: any) {
            setErrorMsg("Connection error: Make sure your tables exist in Supabase.");
        } finally {
            isFetching.current = false;
        }
    }, [session]);

    useEffect(() => {
        if (session) loadData();
    }, [session, loadData]);

    const handleSaveConfig = (key: string, url: string) => {
        localStorage.setItem('supabaseAnonKey', key);
        localStorage.setItem('supabaseUrl', url);
        if (setupClient(key, url)) {
            // Success
        }
    };

    if (isLoading) return <div className="min-h-screen bg-white dark:bg-slate-950 flex items-center justify-center flex-col gap-4"><div className="w-10 h-10 border-4 border-slate-200 border-t-violet-600 rounded-full animate-spin"></div></div>;
    if (!isAppConfigured) return <SystemManagement lookups={lookups} onUpdate={() => {}} language={language} onSaveConfig={handleSaveConfig} isSetupMode={true} />;
    if (!session) return <Login onLoginSuccess={() => loadData()} language={language} setLanguage={setLanguage} supabaseClient={supabaseClient!} />;

    return (
        <div className="flex h-screen bg-slate-50 dark:bg-slate-950 transition-colors duration-300 overflow-hidden" dir={language === 'ar' ? 'rtl' : 'ltr'}>
            <Sidebar currentView={view} setCurrentView={setView} language={language} />
            <div className="flex-1 flex flex-col min-w-0 overflow-hidden">
                <Header user={users.find(u => u.id === session.user.id)} language={language} setLanguage={setLanguage} onSearch={() => {}} onLogout={() => supabaseClient?.auth.signOut()} theme={theme} setTheme={setTheme} isDbConnected={!!session} />
                {errorMsg && (
                    <div className="mx-8 mt-4 p-3 bg-red-50 dark:bg-red-900/20 border border-red-200 rounded-xl flex justify-between items-center animate-in slide-in-from-top-1">
                        <p className="text-[10px] font-black uppercase text-red-600">{errorMsg}</p>
                        <button onClick={() => { localStorage.clear(); window.location.reload(); }} className="text-[9px] font-black bg-red-600 text-white px-3 py-1 rounded-lg">RESET</button>
                    </div>
                )}
                <main className="flex-1 overflow-y-auto p-8 custom-scrollbar">
                    {view === 'dashboard' && <AnalyticsDashboard projects={projects} milestones={milestones} projectManagers={lookups.projectManagers} language={language} />}
                    {view === 'projects' && <Projects allProjects={projects} allUsers={users} language={language} onAddProject={async (d) => { await apiAddProject(d); loadData(); }} onOpenEditModal={setEditingProject} onOpenDeleteModal={setDeletingProject} lookups={lookups} isImportModalOpen={isImportModalOpen} onOpenImportModal={() => setIsImportModalOpen(true)} onCloseImportModal={() => setIsImportModalOpen(false)} onImportProjects={async () => {}} />}
                    {view === 'milestones' && <Milestones allMilestones={milestones} allProjects={projects} language={language} onAddMilestones={async (d) => { await apiAddMilestones(d); loadData(); }} onOpenEditModal={setEditingMilestone} onViewMilestoneDetails={setViewingMilestone} onUpdateMilestone={async (id, d) => { await apiUpdateMilestone(id, d); loadData(); }} lookups={lookups} />}
                    {view === 'team' && <Team allUsers={users} allProjects={projects} language={language} />}
                    {view === 'payments' && <Payments allProjects={projects} allMilestones={milestones} allTeams={lookups.teams} language={language} onUpdateMilestone={async (id, d) => { await apiUpdateMilestone(id, d); loadData(); }} />}
                    {view === 'system' && <SystemManagement lookups={lookups} onUpdate={apiUpdateLookups} language={language} onSaveConfig={handleSaveConfig} />}
                    {view === 'filter' && <MilestoneFilter projects={projects} milestones={milestones} teams={lookups.teams} customers={lookups.customers} projectManagers={lookups.projectManagers} language={language} onUpdateMilestone={async (id, d) => { await apiUpdateMilestone(id, d); loadData(); }} />}
                    {view === 'reports' && <ReportsBuilder projects={projects} milestones={milestones} teams={lookups.teams} language={language} />}
                </main>
            </div>
            {editingProject && <EditProjectModal projectToEdit={editingProject} lookups={lookups} onClose={() => setEditingProject(null)} onUpdateProject={async (id, d) => { await apiUpdateProject(id, d); loadData(); }} language={language} />}
            {editingMilestone && <EditMilestoneModal milestoneToEdit={editingMilestone} allMilestones={milestones} teams={lookups.teams} projects={projects} allMilestoneUpdates={[]} allUsers={users} currentUser={users.find(u => u.id === session.user.id)} onClose={() => setEditingMilestone(null)} onUpdateMilestone={async (id, d) => { await apiUpdateMilestone(id, d); loadData(); }} onAddMilestones={async (d) => { await apiAddMilestones(d); loadData(); }} onAddUpdate={async () => {}} language={language} />}
            {viewingMilestone && <MilestoneDetailModal milestone={viewingMilestone} projects={projects} allMilestoneUpdates={[]} allUsers={users} lookups={lookups} onClose={() => setViewingMilestone(null)} language={language} />}
            {deletingProject && <ConfirmDeleteModal project={deletingProject} onClose={() => setDeletingProject(null)} onConfirm={async () => { await apiDeleteProject(deletingProject.id); setDeletingProject(null); loadData(); }} language={language} />}
            <button onClick={() => setIsChatbotOpen(true)} className="fixed bottom-8 right-8 rtl:left-8 rtl:right-auto bg-slate-900 text-white p-4 rounded-full shadow-xl hover:scale-110 active:scale-95 transition-all z-50"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" viewBox="0 0 20 20" fill="currentColor"><path d="M2 5a2 2 0 012-2h7a2 2 0 012 2v4a2 2 0 01-2 2H9l-3 3v-3H4a2 2 0 01-2-2V5z" /></svg></button>
            <Chatbot isOpen={isChatbotOpen} onClose={() => setIsChatbotOpen(false)} language={language} projects={projects} milestones={milestones} users={users} lookups={lookups} />
        </div>
    );
};

export default App;

import React, { useState, useMemo } from 'react';
import { Project, Milestone, Language, Lookup } from '../types';

interface Field {
    id: string;
    label: string;
    category: 'Project' | 'Milestone';
    accessor: (proj: Project, mile?: Milestone) => string | number | null;
}

interface ReportsBuilderProps {
    projects: Project[];
    milestones: Milestone[];
    teams: Lookup[];
    language: Language;
}

const ReportsBuilder: React.FC<ReportsBuilderProps> = ({ projects, milestones, teams, language }) => {
    const [selectedFields, setSelectedFields] = useState<Field[]>([]);
    const [draggedField, setDraggedField] = useState<Field | null>(null);
    const [searchTerm, setSearchTerm] = useState('');

    const translations = {
        ar: {
            title: "بناء التقارير المخصصة",
            subtitle: "قم بسحب الحقول وتنسيقها لإنشاء تقريرك الخاص.",
            availableFields: "الحقول المتاحة",
            dropZone: "اسحب الحقول هنا لتشكيل أعمدة التقرير",
            preview: "معاينة التقرير",
            export: "تصدير للتقرير",
            searchPlaceholder: "بحث عن حقل...",
            clear: "مسح الكل",
            noFields: "لم يتم اختيار حقول بعد.",
        },
        en: {
            title: "Custom Report Builder",
            subtitle: "Drag and drop fields to design your custom report layout.",
            availableFields: "Available Fields",
            dropZone: "Drop fields here to form report columns",
            preview: "Report Preview",
            export: "Export Report",
            searchPlaceholder: "Search fields...",
            clear: "Clear All",
            noFields: "No fields selected yet.",
        }
    };
    const t = translations[language];

    const AVAILABLE_FIELDS: Field[] = useMemo(() => [
        { id: 'proj_name', label: 'Project Name / اسم المشروع', category: 'Project', accessor: (p) => p.name },
        { id: 'proj_code', label: 'Project Code / كود المشروع', category: 'Project', accessor: (p) => p.projectCode },
        { id: 'proj_pm', label: 'Project Manager / مدير المشروع', category: 'Project', accessor: (p) => p.projectManager?.name || '--' },
        { id: 'proj_customer', label: 'Customer / العميل', category: 'Project', accessor: (p) => p.customer?.name || '--' },
        { id: 'proj_status', label: 'Project Status / حالة المشروع', category: 'Project', accessor: (p) => p.status?.name || '--' },
        { id: 'proj_progress', label: 'Progress / التقدم', category: 'Project', accessor: (p) => `${p.progress}%` },
        { id: 'mile_title', label: 'Milestone Title / اسم الدفعة', category: 'Milestone', accessor: (_, m) => m?.title || '--' },
        { id: 'mile_status', label: 'Milestone Status / حالة المعلم', category: 'Milestone', accessor: (_, m) => m?.status || '--' },
        { id: 'mile_amount', label: 'Milestone Value / قيمة الدفعة', category: 'Milestone', accessor: (_, m) => m?.hasPayment ? m.paymentAmount : '--' },
        { 
            id: 'mile_month_year', 
            label: 'Month-Year / شهر وسنة المعلم', 
            category: 'Milestone', 
            accessor: (_, m) => {
                if (!m?.dueDate) return '--';
                const date = new Date(m.dueDate);
                return date.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { month: 'long', year: 'numeric' });
            }
        },
        { 
            id: 'team_name', 
            label: 'Team / الفريق المسؤول', 
            category: 'Milestone', 
            accessor: (p, m) => {
                const teamId = m?.teamId || p.teamId;
                return teams.find(t => t.id === teamId)?.name || '--';
            }
        },
        { id: 'mile_pay_status', label: 'Payment Status / حالة الدفعة', category: 'Milestone', accessor: (_, m) => m?.paymentStatus || '--' },
        { id: 'mile_due', label: 'Due Date / تاريخ الاستحقاق', category: 'Milestone', accessor: (_, m) => m?.dueDate ? new Date(m.dueDate).toLocaleDateString() : '--' },
        { id: 'proj_country', label: 'Country / البلد', category: 'Project', accessor: (p) => p.country?.name || '--' },
    ], [teams, language]);

    const filteredAvailableFields = AVAILABLE_FIELDS.filter(f => 
        !selectedFields.find(sf => sf.id === f.id) && 
        f.label.toLowerCase().includes(searchTerm.toLowerCase())
    );

    const handleDragStart = (field: Field) => {
        setDraggedField(field);
    };

    const handleDrop = (e: React.DragEvent) => {
        e.preventDefault();
        if (draggedField && !selectedFields.find(f => f.id === draggedField.id)) {
            setSelectedFields([...selectedFields, draggedField]);
            setDraggedField(null);
        }
    };

    const removeField = (fieldId: string) => {
        setSelectedFields(selectedFields.filter(f => f.id !== fieldId));
    };

    const reportData = useMemo(() => {
        const rows: any[] = [];
        projects.forEach(p => {
            const pMilestones = milestones.filter(m => m.projectId === p.id);
            if (pMilestones.length > 0) {
                pMilestones.forEach(m => {
                    const row: any = {};
                    selectedFields.forEach(f => {
                        row[f.id] = f.accessor(p, m);
                    });
                    rows.push(row);
                });
            } else {
                const row: any = {};
                selectedFields.forEach(f => {
                    row[f.id] = f.accessor(p);
                });
                rows.push(row);
            }
        });
        return rows;
    }, [projects, milestones, selectedFields]);

    const handleExport = () => {
        if (selectedFields.length === 0) return;
        const headers = selectedFields.map(f => f.label).join(',');
        const rows = reportData.map(row => 
            selectedFields.map(f => `"${String(row[f.id] || '').replace(/"/g, '""')}"`).join(',')
        ).join('\n');

        const csvContent = "\uFEFF" + headers + '\n' + rows;
        const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
        const link = document.createElement('a');
        link.href = URL.createObjectURL(blob);
        link.setAttribute('download', `PioTech_Custom_Report_${new Date().toISOString().slice(0,10)}.csv`);
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
    };

    return (
        <div className="space-y-8 max-w-[1600px] mx-auto pb-20">
            <div className="flex justify-between items-end">
                <div>
                    <h1 className="text-3xl font-black text-slate-800 dark:text-white uppercase tracking-tight">{t.title}</h1>
                    <p className="text-slate-400 font-bold text-[10px] mt-2 uppercase tracking-widest">{t.subtitle}</p>
                </div>
                <div className="flex gap-3">
                    <button onClick={() => setSelectedFields([])} className="px-6 py-2.5 text-[10px] font-black text-slate-400 border border-slate-200 dark:border-slate-800 rounded-xl hover:bg-slate-50 uppercase tracking-widest">{t.clear}</button>
                    <button onClick={handleExport} disabled={selectedFields.length === 0} className="px-8 py-2.5 text-[10px] font-black text-white bg-violet-600 rounded-xl hover:bg-violet-700 transition-all uppercase tracking-widest shadow-xl shadow-violet-500/20 disabled:opacity-50">{t.export}</button>
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
                {/* Available Fields - Draggable Items */}
                <div className="lg:col-span-3 space-y-4">
                    <div className="bg-white dark:bg-slate-900 border border-slate-100 dark:border-slate-800 p-6 rounded-[2.5rem] shadow-sm flex flex-col h-[600px]">
                        <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-4">{t.availableFields}</h2>
                        <div className="relative mb-6">
                            <input 
                                type="text" 
                                value={searchTerm}
                                onChange={(e) => setSearchTerm(e.target.value)}
                                placeholder={t.searchPlaceholder} 
                                className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-700 p-3 rounded-2xl text-xs outline-none focus:ring-1 focus:ring-violet-500" 
                            />
                        </div>
                        <div className="flex-1 overflow-y-auto custom-scrollbar space-y-2 pe-2">
                            {filteredAvailableFields.map(field => (
                                <div
                                    key={field.id}
                                    draggable
                                    onDragStart={() => handleDragStart(field)}
                                    className="p-4 bg-slate-50 dark:bg-slate-800/50 border border-slate-100 dark:border-slate-800 rounded-2xl cursor-grab active:cursor-grabbing hover:border-violet-300 dark:hover:border-violet-700 group transition-all"
                                >
                                    <div className="flex items-center gap-3">
                                        <div className="w-8 h-8 rounded-lg bg-white dark:bg-slate-900 flex items-center justify-center shadow-sm group-hover:text-violet-600">
                                            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M4 6h16M4 12h16M4 18h16" /></svg>
                                        </div>
                                        <div>
                                            <p className="text-[10px] font-black text-slate-800 dark:text-white truncate">{field.label.split('/')[language === 'ar' ? 1 : 0]}</p>
                                            <p className="text-[8px] font-bold text-slate-400 uppercase tracking-widest">{field.category}</p>
                                        </div>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>

                {/* Drop Zone & Preview */}
                <div className="lg:col-span-9 space-y-8">
                    {/* Columns Selector */}
                    <div 
                        onDragOver={(e) => e.preventDefault()}
                        onDrop={handleDrop}
                        className="bg-slate-50 dark:bg-slate-900/40 border-2 border-dashed border-slate-200 dark:border-slate-800 p-8 rounded-[3rem] min-h-[160px] flex flex-wrap gap-3 items-center justify-center transition-colors hover:bg-slate-100/50 dark:hover:bg-slate-800/20"
                    >
                        {selectedFields.length === 0 ? (
                            <div className="text-center opacity-30">
                                <svg className="w-12 h-12 mx-auto mb-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="1.5" d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" /></svg>
                                <p className="text-xs font-black uppercase tracking-widest">{t.dropZone}</p>
                            </div>
                        ) : (
                            selectedFields.map(field => (
