                    onLogout={() => supabaseClient?.auth.signOut()} 
                    theme={theme} 
                    setTheme={setTheme} 
                    isDbConnected={!!session}
                    onToggleSidebar={() => setIsSidebarOpen(!isSidebarOpen)}
                />

                {/* AI Progress Bar */}
                {isAnalyzing && (
                    <div className="h-0.5 w-full bg-violet-100 dark:bg-violet-900/30 overflow-hidden">
