            <div className={`fixed inset-y-0 z-50 lg:relative lg:z-auto transition-transform duration-300 transform ${isSidebarOpen ? 'translate-x-0' : (language === 'ar' ? 'translate-x-full' : '-translate-x-full')} lg:translate-x-0`}>
