                                        <span className={`w-1.5 h-1.5 rounded-full ${field.category === 'Project' ? 'bg-violet-500' : 'bg-blue-500'}`}></span>
                                        <span className="text-[10px] font-black text-slate-700 dark:text-slate-200">{field.label}</span>
