const mapDbToIssue = (db: any): Issue => ({
    id: db.id,
    title: db.title,
    description: db.description || '',
    status: (db.status || IssueStatus.Open) as IssueStatus,
    priority: (db.priority || IssuePriority.Medium) as IssuePriority,
    projectId: db.project_id,
    milestoneId: db.milestone_id,
    assigneeId: db.assignee_id,
    reporterId: db.reporter_id,
    createdAt: db.created_at
});

const mapIssueToDb = (data: Partial<Issue>) => {
    const db: any = {};
    if (data.title !== undefined) db.title = data.title;
    if (data.description !== undefined) db.description = data.description;
    if (data.status !== undefined) db.status = data.status;
    if (data.priority !== undefined) db.priority = data.priority;
    if (data.projectId !== undefined) db.project_id = data.projectId;
    if (data.milestoneId !== undefined) db.milestone_id = data.milestoneId;
    if (data.assigneeId !== undefined) db.assignee_id = data.assigneeId;
    if (data.reporterId !== undefined) db.reporter_id = data.reporterId;
    return db;
};

