    const supabase = getSupabase();
    if (!supabase) throw new Error("Supabase client not initialized");
    const { data, error } = await supabase.from('issues').update(mapIssueToDb(issueData)).eq('id', id).select();
    if (error) throw error;
    return mapDbToIssue(data[0]);
};

