import { getSupabase } from './supabaseClient';
import { Project, Milestone, User, Lookups, MilestoneStatus, PaymentStatus, MaintenanceContract, Issue, IssueStatus, IssuePriority, Notification, Lookup } from '../types';

const mapDbToNotification = (db: any): Notification => ({
    id: db.id,
    userId: db.user_id,
    title: db.title,
    message: db.message,
    type: db.type,
    isRead: db.is_read,
    createdAt: db.created_at,
