    const { error } = await supabase.from('maintenance_contracts').insert([{
        type: c.type, month: c.month, year: c.year, customer_id: c.customerId, project_code: c.projectCode, total_amount: c.totalAmount, collected_amount: c.collectedAmount, lost_amount: c.lostAmount, start_date: c.startDate, end_date: c.endDate, notes: c.notes
