import React, { useState, useMemo } from 'react';
import { Issue, Project, Milestone, User, Language, IssueStatus, IssuePriority } from '../types';
import SearchableSelect from './SearchableSelect';

interface IssuesProps {
    allIssues: Issue[];
    allProjects: Project[];
    allMilestones: Milestone[];
    allUsers: User[];
    language: Language;
    onAddIssue: (data: Omit<Issue, 'id' | 'createdAt'>) => Promise<void>;
    onUpdateIssue: (id: string, data: Partial<Issue>) => Promise<void>;
    currentUser: User | undefined;
}

const Issues: React.FC<IssuesProps> = ({ allIssues, allProjects, allMilestones, allUsers, language, onAddIssue, onUpdateIssue, currentUser }) => {
    const [isAddModalOpen, setIsAddModalOpen] = useState(false);
    const [selectedProjectId, setSelectedProjectId] = useState('all');
    const [selectedStatus, setSelectedStatus] = useState('all');
    const [onlyMyIssues, setOnlyMyIssues] = useState(false);

    const t = translations[language];

    // This specifically looks for users with type 'PS' which we set in our SQL sync
    const psUsers = useMemo(() => allUsers.filter(u => u.type === 'PS'), [allUsers]);

    const filteredIssues = useMemo(() => {
        return allIssues.filter(i => {
            const projectMatch = selectedProjectId === 'all' || i.projectId === selectedProjectId;
            const statusMatch = selectedStatus === 'all' || i.status === selectedStatus;
            const userMatch = !onlyMyIssues || (currentUser && i.assigneeId === currentUser.id);
            return projectMatch && statusMatch && userMatch;
        });
    }, [allIssues, selectedProjectId, selectedStatus, onlyMyIssues, currentUser]);

    const priorityColors = {
        [IssuePriority.Critical]: 'bg-red-500 text-white',
        [IssuePriority.High]: 'bg-orange-500 text-white',
        [IssuePriority.Medium]: 'bg-yellow-500 text-slate-900',
        [IssuePriority.Low]: 'bg-blue-400 text-white',
    };

    const statusColors = {
        [IssueStatus.Open]: 'bg-slate-100 text-slate-700 dark:bg-slate-800 dark:text-slate-300',
        [IssueStatus.InProgress]: 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-300',
        [IssueStatus.Resolved]: 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-300',
        [IssueStatus.Closed]: 'bg-slate-200 text-slate-500 dark:bg-slate-700 dark:text-slate-400 line-through',
    };

    return (
        <div className="space-y-8">
            <div className="flex flex-col md:flex-row justify-between items-center gap-4">
                <div>
                    <h1 className="text-3xl font-black text-slate-800 dark:text-white uppercase tracking-tight">{t.title}</h1>
                    <p className="text-slate-400 font-bold text-xs mt-1 uppercase tracking-widest">{t.subtitle}</p>
                </div>
                <div className="flex items-center gap-4">
                    <button 
                        onClick={() => setOnlyMyIssues(!onlyMyIssues)}
                        className={`px-5 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all border ${onlyMyIssues ? 'bg-violet-100 border-violet-200 text-violet-700' : 'bg-white border-slate-200 text-slate-500 dark:bg-slate-900 dark:border-slate-800'}`}
                    >
                        {onlyMyIssues ? t.allIssues : t.myIssues}
                    </button>
                    <button onClick={() => setIsAddModalOpen(true)} className="px-6 py-2.5 bg-violet-600 text-white text-[10px] font-black uppercase tracking-widest rounded-xl hover:bg-violet-700 shadow-lg shadow-violet-500/20 flex items-center gap-2">
                        <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 4v16m8-8H4"/></svg>
                        {t.newIssue}
                    </button>
                </div>
            </div>

            <div className="bg-slate-50 dark:bg-slate-900/50 p-4 rounded-[2rem] border border-slate-100 dark:border-slate-800 flex flex-wrap gap-4">
                <div className="flex-1 min-w-[200px]">
                    <SearchableSelect 
                        options={[{value:'all', label:t.allProjects}, ...allProjects.map(p => ({value:p.id, label:p.name}))]} 
                        value={selectedProjectId} 
                        onChange={setSelectedProjectId} 
                        placeholder={t.allProjects} 
                        language={language} 
                    />
                </div>
                <div className="flex-1 min-w-[200px]">
                    <select value={selectedStatus} onChange={e => setSelectedStatus(e.target.value)} className="w-full p-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-xs font-bold outline-none">
                        <option value="all">{t.allStatuses}</option>
                        {Object.values(IssueStatus).map(s => <option key={s} value={s}>{s}</option>)}
                    </select>
                </div>
            </div>

            {filteredIssues.length > 0 ? (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    {filteredIssues.map(issue => (
                        <div key={issue.id} className={`bg-white dark:bg-slate-900 border p-6 rounded-[2rem] shadow-sm hover:shadow-md transition-all group flex flex-col justify-between h-full ${issue.assigneeId === currentUser?.id ? 'ring-2 ring-violet-500/20 border-violet-200' : 'border-slate-100 dark:border-slate-800'}`}>
                            <div>
                                <div className="flex justify-between items-start mb-4">
                                    <span className={`px-2 py-0.5 rounded-lg text-[8px] font-black uppercase ${priorityColors[issue.priority]}`}>{issue.priority}</span>
                                    <select 
                                        value={issue.status} 
                                        onChange={e => onUpdateIssue(issue.id, { status: e.target.value as IssueStatus })}
                                        className={`px-3 py-1 rounded-full text-[10px] font-black uppercase outline-none border-none cursor-pointer ${statusColors[issue.status]}`}
                                    >
                                        {Object.values(IssueStatus).map(s => <option key={s} value={s}>{s}</option>)}
                                    </select>
                                </div>
                                <h3 className="text-sm font-black text-slate-800 dark:text-white mb-2">{issue.title}</h3>
                                <p className="text-xs text-slate-500 dark:text-slate-400 mb-6 line-clamp-2">{issue.description}</p>

                                <div className="space-y-2 mb-6">
                                    <div className="flex items-center gap-2 text-[10px]">
                                        <span className="text-slate-400 uppercase font-black">{t.project}:</span>
                                        <span className="text-violet-600 dark:text-violet-400 font-bold truncate">{issue.project?.name}</span>
                                    </div>
                                    {issue.milestoneId && (
                                        <div className="flex items-center gap-2 text-[10px]">
                                            <span className="text-slate-400 uppercase font-black">{t.milestone}:</span>
                                            <span className="text-blue-500 font-bold">{allMilestones.find(m => m.id === issue.milestoneId)?.title}</span>
                                        </div>
                                    )}
                                </div>
                            </div>

                            <div className="pt-4 border-t border-slate-50 dark:border-slate-800 flex items-center justify-between">
                                <div className="flex items-center gap-2">
                                    <div className="w-8 h-8 rounded-full bg-slate-100 dark:bg-slate-800 flex items-center justify-center border border-white dark:border-slate-700">
                                        <img src={issue.assignee?.avatarUrl || `https://ui-avatars.com/api/?name=${issue.assignee?.name || '?'}&background=8b5cf6&color=fff`} className="w-full h-full rounded-full" />
                                    </div>
                                    <div>
                                        <p className="text-[8px] font-black text-slate-400 uppercase leading-none mb-1">{t.assignedTo}</p>
                                        <p className={`text-[10px] font-black truncate max-w-[80px] ${issue.assigneeId === currentUser?.id ? 'text-violet-600 font-black' : 'text-slate-700 dark:text-slate-200'}`}>{issue.assigneeId === currentUser?.id ? t.you : (issue.assignee?.name || t.unassigned)}</p>
                                    </div>
                                </div>
                                <div className="text-end">
                                    <p className="text-[8px] font-black text-slate-400 uppercase leading-none mb-1">{t.reportedAt}</p>
                                    <p className="text-[10px] font-bold text-slate-500">{new Date(issue.createdAt).toLocaleDateString()}</p>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            ) : (
                <div className="py-20 text-center text-[10px] font-black uppercase text-slate-300 tracking-[0.4em]">{t.noIssues}</div>
            )}

            {isAddModalOpen && (
                <AddIssueModal 
                    onClose={() => setIsAddModalOpen(false)} 
                    projects={allProjects} 
                    milestones={allMilestones} 
                    users={psUsers} // Now lists ONLY system users who are 'PS'
                    language={language} 
                    onSave={async (d) => { 
                        await onAddIssue({...d, reporterId: currentUser?.id || ''}); 
                        setIsAddModalOpen(false); 
                    }}
                />
            )}
        </div>
    );
};

const AddIssueModal: React.FC<{ onClose: () => void, projects: Project[], milestones: Milestone[], users: User[], language: Language, onSave: (d: any) => Promise<void> }> = ({ onClose, projects, milestones, users, language, onSave }) => {
    const t = translations[language];
    const [formData, setFormData] = useState({ title: '', description: '', projectId: '', milestoneId: '', assigneeId: '', priority: IssuePriority.Medium, status: IssueStatus.Open });
    const [isSaving, setIsSaving] = useState(false);
    const [errorMsg, setErrorMsg] = useState<string | null>(null);

    const filteredMilestones = useMemo(() => milestones.filter(m => m.projectId === formData.projectId), [milestones, formData.projectId]);

    const inputClasses = "w-full p-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl text-xs font-bold outline-none focus:ring-2 focus:ring-violet-500 transition-all";

    const handleSave = async () => {
        if (!formData.title || !formData.projectId) {
            setErrorMsg(language === 'ar' ? "يرجى ملء الحقول الإلزامية (العنوان والمشروع)" : "Title and Project are required");
            return;
        }
        setIsSaving(true);
        setErrorMsg(null);
        try {
            await onSave(formData);
        } catch (e: any) {
            setErrorMsg(e.message || "Failed to save issue.");
            setIsSaving(false);
        }
    };

    return (
        <div className="fixed inset-0 bg-slate-950/80 backdrop-blur-md flex items-center justify-center z-[200] p-4">
            <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-[2.5rem] shadow-2xl w-full max-w-xl overflow-hidden animate-in zoom-in-95" dir={language === 'ar' ? 'rtl' : 'ltr'}>
                <div className="p-8">
                    <div className="flex justify-between items-center mb-8">
                        <h2 className="text-lg font-black text-slate-800 dark:text-white uppercase tracking-tight">{t.newIssue}</h2>
                        <button onClick={onClose} className="p-2 text-slate-400 hover:text-slate-800 transition-colors">&times;</button>
                    </div>

                    {errorMsg && (
                        <div className="mb-6 p-4 bg-red-50 dark:bg-red-900/20 border border-red-100 dark:border-red-800 rounded-2xl">
                            <p className="text-[10px] font-black text-red-600 uppercase tracking-widest">{errorMsg}</p>
                        </div>
                    )}

                    <div className="space-y-6">
                        <div>
                            <label className="block text-[10px] font-black text-slate-400 uppercase mb-2 ps-1">{t.issueTitle} *</label>
                            <input type="text" value={formData.title} onChange={e => setFormData({...formData, title: e.target.value})} className={inputClasses} placeholder={t.issueTitle} disabled={isSaving} />
                        </div>
                        <div>
                            <label className="block text-[10px] font-black text-slate-400 uppercase mb-2 ps-1">{t.description}</label>
                            <textarea value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} className={inputClasses + " h-24 resize-none"} disabled={isSaving} />
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="block text-[10px] font-black text-slate-400 uppercase mb-2 ps-1">{t.project} *</label>
                                <select value={formData.projectId} onChange={e => setFormData({...formData, projectId: e.target.value, milestoneId: ''})} className={inputClasses} disabled={isSaving}>
                                    <option value="">{t.selectProject}</option>
                                    {projects.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
                                </select>
                            </div>
                            <div>
                                <label className="block text-[10px] font-black text-slate-400 uppercase mb-2 ps-1">{t.milestone}</label>
                                <select value={formData.milestoneId} onChange={e => setFormData({...formData, milestoneId: e.target.value})} className={inputClasses} disabled={!formData.projectId || isSaving}>
                                    <option value="">{t.selectMilestone}</option>
                                    {filteredMilestones.map(m => <option key={m.id} value={m.id}>{m.title}</option>)}
                                </select>
                            </div>
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="block text-[10px] font-black text-slate-400 uppercase mb-2 ps-1">{t.assignedTo}</label>
                                <select value={formData.assigneeId} onChange={e => setFormData({...formData, assigneeId: e.target.value})} className={inputClasses} disabled={isSaving}>
                                    <option value="">{t.selectAssignee}</option>
                                    {users.map(u => <option key={u.id} value={u.id}>{u.name}</option>)}
                                </select>
                            </div>
                            <div>
                                <label className="block text-[10px] font-black text-slate-400 uppercase mb-2 ps-1">{t.priority}</label>
                                <select value={formData.priority} onChange={e => setFormData({...formData, priority: e.target.value as IssuePriority})} className={inputClasses} disabled={isSaving}>
                                    {Object.values(IssuePriority).map(p => <option key={p} value={p}>{p}</option>)}
                                </select>
                            </div>
                        </div>
                    </div>

                    <div className="flex justify-end gap-3 mt-10">
                        <button onClick={onClose} className="px-6 py-3 text-[10px] font-black text-slate-400 uppercase tracking-widest hover:text-slate-600" disabled={isSaving}>{t.cancel}</button>
                        <button 
                            onClick={handleSave} 
                            disabled={isSaving}
                            className="px-10 py-3 bg-violet-600 text-white text-[10px] font-black uppercase tracking-widest rounded-xl hover:bg-violet-700 transition-all shadow-lg shadow-violet-500/20 flex items-center gap-2"
                        >
                            {isSaving && <div className="w-3 h-3 border-2 border-white/20 border-t-white rounded-full animate-spin"></div>}
                            {isSaving ? (language === 'ar' ? 'جاري الحفظ...' : 'Saving...') : t.saveIssue}
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );
}

