    );
};

const IssueDetailModal: React.FC<{ issue: Issue, onClose: () => void, language: Language, currentUser?: User, onUpdateStatus: (s: IssueStatus) => Promise<void>, onAddComment: (c: string) => Promise<void> }> = ({ issue, onClose, language, currentUser, onUpdateStatus, onAddComment }) => {
    const t = translations[language];
    const [comment, setComment] = useState('');
    const [isSaving, setIsSaving] = useState(false);

    const isAssignee = currentUser?.id === issue.assigneeId;

    const handleAddComment = async () => {
        if (!comment.trim()) return;
        setIsSaving(true);
        try {
            await onAddComment(comment);
            setComment('');
        } finally {
            setIsSaving(false);
        }
    };

    return (
        <div className="fixed inset-0 bg-slate-950/80 backdrop-blur-md flex items-center justify-center z-[200] p-4">
            <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-[2.5rem] shadow-2xl w-full max-w-4xl overflow-hidden animate-in zoom-in-95 flex flex-col md:flex-row h-[80vh]" dir={language === 'ar' ? 'rtl' : 'ltr'}>
                {/* Details Section */}
                <div className="flex-1 p-8 overflow-y-auto custom-scrollbar border-e border-slate-50 dark:border-slate-800">
                    <div className="flex justify-between items-center mb-6">
                        <span className="px-2 py-1 bg-violet-100 text-violet-700 text-[10px] font-black rounded-lg uppercase tracking-widest">{issue.project?.name}</span>
                        <button onClick={onClose} className="text-slate-400 hover:text-slate-800 transition-colors">&times;</button>
                    </div>
                    <h2 className="text-2xl font-black text-slate-800 dark:text-white mb-4 leading-tight">{issue.title}</h2>
                    <p className="text-sm text-slate-600 dark:text-slate-300 whitespace-pre-wrap mb-8 bg-slate-50 dark:bg-slate-800/50 p-6 rounded-3xl">{issue.description}</p>

                    <div className="grid grid-cols-2 gap-6">
                        <div>
                            <p className="text-[10px] font-black text-slate-400 uppercase mb-2 ps-1">{t.status}</p>
                            <select 
                                value={issue.status} 
                                disabled={!isAssignee}
                                onChange={(e) => onUpdateStatus(e.target.value as IssueStatus)}
                                className="w-full p-3 bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-800 rounded-2xl text-xs font-bold"
                            >
                                {Object.values(IssueStatus).map(s => <option key={s} value={s}>{s}</option>)}
                            </select>
                        </div>
                        <div>
                            <p className="text-[10px] font-black text-slate-400 uppercase mb-2 ps-1">{t.assignedTo}</p>
                            <div className="flex items-center gap-3 p-3 bg-slate-50 dark:bg-slate-800 rounded-2xl">
                                <img src={issue.assignee?.avatarUrl || `https://ui-avatars.com/api/?name=${issue.assignee?.name || '?'}&background=8b5cf6&color=fff`} className="w-6 h-6 rounded-full" />
                                <span className="text-xs font-bold text-slate-700 dark:text-slate-200">{issue.assignee?.name}</span>
                            </div>
                        </div>
                    </div>
                </div>

                {/* Comments Section */}
                <div className="w-full md:w-[400px] bg-slate-50 dark:bg-slate-900/50 flex flex-col h-full">
                    <div className="p-6 border-b border-slate-100 dark:border-slate-800 flex justify-between items-center">
                        <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest">{t.comments}</h3>
                        <span className="text-[10px] font-black text-violet-600 bg-violet-100 px-2 py-0.5 rounded-full">{(issue.comments || []).length}</span>
                    </div>

                    <div className="flex-1 p-6 overflow-y-auto custom-scrollbar space-y-6">
                        {(issue.comments || []).length > 0 ? issue.comments?.map(c => (
                            <div key={c.id} className="flex gap-3">
                                <img src={c.user?.avatarUrl || `https://ui-avatars.com/api/?name=${c.user?.name || '?'}&background=a78bfa&color=fff`} className="w-8 h-8 rounded-full mt-1 shrink-0" />
                                <div className="space-y-1">
                                    <div className="flex items-center gap-2">
                                        <span className="text-[10px] font-black text-slate-700 dark:text-slate-200">{c.user?.name}</span>
                                        <span className="text-[8px] font-bold text-slate-400">{new Date(c.createdAt).toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { day: 'numeric', month: 'short', hour: 'numeric', minute: '2-digit' })}</span>
                                    </div>
                                    <div className="bg-white dark:bg-slate-800 p-3 rounded-2xl rounded-tr-none rtl:rounded-tr-2xl rtl:rounded-tl-none text-xs text-slate-600 dark:text-slate-300 shadow-sm">
                                        {c.content}
                                    </div>
                                </div>
                            </div>
                        )) : (
                            <div className="h-full flex flex-col items-center justify-center opacity-30 italic text-[10px] font-black uppercase">
                                {t.noComments}
                            </div>
                        )}
                    </div>

                    {/* Add Comment Input - Restricted to Assignee */}
                    <div className="p-6 border-t border-slate-100 dark:border-slate-800 bg-white dark:bg-slate-900">
                        {isAssignee ? (
                            <div className="relative">
                                <textarea 
                                    value={comment}
                                    onChange={(e) => setComment(e.target.value)}
                                    placeholder={t.addCommentPlaceholder}
                                    className="w-full p-4 pe-12 bg-slate-100 dark:bg-slate-800 rounded-3xl text-xs font-bold outline-none focus:ring-2 focus:ring-violet-500 transition-all resize-none h-24"
                                />
                                <button 
                                    onClick={handleAddComment}
                                    disabled={isSaving || !comment.trim()}
                                    className="absolute bottom-4 right-4 rtl:right-auto rtl:left-4 p-2 bg-violet-600 text-white rounded-full hover:scale-110 active:scale-95 transition-all disabled:opacity-50"
                                >
                                    <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8"/></svg>
                                </button>
                            </div>
                        ) : (
                            <p className="text-[10px] font-black text-center text-slate-400 uppercase tracking-widest">{t.assigneeOnlyNote}</p>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
};

const AddIssueModal: React.FC<{ onClose: () => void, projects: Project[], milestones: Milestone[], users: User[], language: Language, onSave: (d: any) => Promise<void> }> = ({ onClose, projects, milestones, users, language, onSave }) => {
    const t = translations[language];
    const [formData, setFormData] = useState({ title: '', description: '', projectId: '', milestoneId: '', assigneeId: '', priority: IssuePriority.Medium, status: IssueStatus.Open });
    const [isSaving, setIsSaving] = useState(false);
    const [errorMsg, setErrorMsg] = useState<string | null>(null);

    const filteredMilestones = useMemo(() => milestones.filter(m => m.projectId === formData.projectId), [milestones, formData.projectId]);

    const inputClasses = "w-full p-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl text-xs font-bold outline-none focus:ring-2 focus:ring-violet-500 transition-all";

    const handleSave = async () => {
        if (!formData.title || !formData.projectId) {
            setErrorMsg(language === 'ar' ? "يرجى ملء الحقول الإلزامية (العنوان والمشروع)" : "Title and Project are required");
            return;
        }
        setIsSaving(true);
        setErrorMsg(null);
        try {
            await onSave(formData);
        } catch (e: any) {
            setErrorMsg(e.message || "Failed to save issue.");
            setIsSaving(false);
        }
    };

    return (
        <div className="fixed inset-0 bg-slate-950/80 backdrop-blur-md flex items-center justify-center z-[200] p-4">
            <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-[2.5rem] shadow-2xl w-full max-w-xl overflow-hidden animate-in zoom-in-95" dir={language === 'ar' ? 'rtl' : 'ltr'}>
                <div className="p-8">
                    <div className="flex justify-between items-center mb-8">
                        <h2 className="text-lg font-black text-slate-800 dark:text-white uppercase tracking-tight">{t.newIssue}</h2>
                        <button onClick={onClose} className="p-2 text-slate-400 hover:text-slate-800 transition-colors">&times;</button>
                    </div>

                    {errorMsg && (
                        <div className="mb-6 p-4 bg-red-50 dark:bg-red-900/20 border border-red-100 dark:border-red-800 rounded-2xl">
                            <p className="text-[10px] font-black text-red-600 uppercase tracking-widest">{errorMsg}</p>
                        </div>
                    )}

                    <div className="space-y-6">
                        <div>
                            <label className="block text-[10px] font-black text-slate-400 uppercase mb-2 ps-1">{t.issueTitle} *</label>
                            <input type="text" value={formData.title} onChange={e => setFormData({...formData, title: e.target.value})} className={inputClasses} placeholder={t.issueTitle} disabled={isSaving} />
                        </div>
                        <div>
                            <label className="block text-[10px] font-black text-slate-400 uppercase mb-2 ps-1">{t.description}</label>
                            <textarea value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} className={inputClasses + " h-24 resize-none"} disabled={isSaving} />
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="block text-[10px] font-black text-slate-400 uppercase mb-2 ps-1">{t.project} *</label>
                                <select value={formData.projectId} onChange={e => setFormData({...formData, projectId: e.target.value, milestoneId: ''})} className={inputClasses} disabled={isSaving}>
                                    <option value="">{t.selectProject}</option>
                                    {projects.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
                                </select>
                            </div>
                            <div>
                                <label className="block text-[10px] font-black text-slate-400 uppercase mb-2 ps-1">{t.milestone}</label>
                                <select value={formData.milestoneId} onChange={e => setFormData({...formData, milestoneId: e.target.value})} className={inputClasses} disabled={!formData.projectId || isSaving}>
                                    <option value="">{t.selectMilestone}</option>
                                    {filteredMilestones.map(m => <option key={m.id} value={m.id}>{m.title}</option>)}
                                </select>
                            </div>
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="block text-[10px] font-black text-slate-400 uppercase mb-2 ps-1">{t.assignedTo}</label>
                                <select value={formData.assigneeId} onChange={e => setFormData({...formData, assigneeId: e.target.value})} className={inputClasses} disabled={isSaving}>
                                    <option value="">{t.selectAssignee}</option>
                                    {users.map(u => <option key={u.id} value={u.id}>{u.name}</option>)}
                                </select>
                            </div>
                            <div>
                                <label className="block text-[10px] font-black text-slate-400 uppercase mb-2 ps-1">{t.priority}</label>
                                <select value={formData.priority} onChange={e => setFormData({...formData, priority: e.target.value as IssuePriority})} className={inputClasses} disabled={isSaving}>
                                    {Object.values(IssuePriority).map(p => <option key={p} value={p}>{p}</option>)}
                                </select>
                            </div>
                        </div>
                    </div>

                    <div className="flex justify-end gap-3 mt-10">
                        <button onClick={onClose} className="px-6 py-3 text-[10px] font-black text-slate-400 uppercase tracking-widest hover:text-slate-600" disabled={isSaving}>{t.cancel}</button>
                        <button 
                            onClick={handleSave} 
                            disabled={isSaving}
                            className="px-10 py-3 bg-violet-600 text-white text-[10px] font-black uppercase tracking-widest rounded-xl hover:bg-violet-700 transition-all shadow-lg shadow-violet-500/20 flex items-center gap-2"
                        >
                            {isSaving && <div className="w-3 h-3 border-2 border-white/20 border-t-white rounded-full animate-spin"></div>}
                            {isSaving ? (language === 'ar' ? 'جاري الحفظ...' : 'Saving...') : t.saveIssue}
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );
}

const translations = {
