                                    )) : (
                                        <tr>
                                            <td colSpan={displayColumns.length} className="px-6 py-20 text-center text-[10px] font-black text-slate-200 uppercase tracking-[0.4em]">{t.noResults}</td>
                                        </tr>
                                    )}
                                </tbody>
                            </table>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

