const ProjectIssuesWidget: React.FC<{ projects: Project[], issues: Issue[], language: Language }> = ({ projects, issues, language }) => {
    const t = translations[language];
    const data = useMemo(() => {
        return projects.map(p => ({
            name: p.name,
            count: issues.filter(i => i.projectId === p.id && i.status !== IssueStatus.Closed).length
        })).filter(d => d.count > 0).sort((a, b) => b.count - a.count).slice(0, 10);
    }, [projects, issues]);

    const maxCount = Math.max(...data.map(d => d.count), 1);

    return (
        <WidgetWrapper title={t.projectIssuesTitle}>
            <div className="space-y-4">
                {data.length > 0 ? data.map((d, i) => (
                    <div key={i} className="space-y-1">
                        <div className="flex justify-between items-center text-[10px] font-black uppercase">
                            <span className="text-slate-700 dark:text-slate-300 truncate w-40">{d.name}</span>
                            <span className="text-red-500">{d.count} {t.issuesCount}</span>
                        </div>
                        <div className="w-full h-1.5 bg-slate-100 dark:bg-slate-800 rounded-full overflow-hidden">
                            <div className="h-full bg-red-500" style={{ width: `${(d.count / maxCount) * 100}%` }}></div>
                        </div>
                    </div>
                )) : <div className="py-10 text-center opacity-20 italic text-[10px] font-black">{t.noIssues}</div>}
            </div>
        </WidgetWrapper>
    );
};

