                    language={language} setLanguage={setLanguage} onSearch={handleAiSearch} onLogout={() => supabaseClient?.auth.signOut()} 
                    theme={theme} setTheme={setTheme} isDbConnected={!!session} onToggleSidebar={() => setIsSidebarOpen(!isSidebarOpen)}
                    notifications={notifications} onNotificationRead={loadData}
                />

                {isAnalyzing && <div className="h-0.5 w-full bg-violet-600/20 overflow-hidden"><div className="h-full bg-violet-600 animate-[loading_2s_ease-in-out_infinite]" style={{ width: '30%', transformOrigin: 'left' }}></div></div>}

                <main className="flex-1 overflow-y-auto p-4 lg:p-8 custom-scrollbar">
                    {view === 'dashboard' && <AnalyticsDashboard projects={projects} milestones={milestones} issues={issues} users={users} projectManagers={lookups.projectManagers} language={language} />}
                    {view === 'projects' && <Projects allProjects={projects} allUsers={users} language={language} onAddProject={async (d) => { await apiAddProject(d); loadData(); }} onOpenEditModal={setEditingProject} onOpenDeleteModal={setDeletingProject} lookups={lookups} isImportModalOpen={isImportModalOpen} onOpenImportModal={() => setIsImportModalOpen(true)} onCloseImportModal={() => setIsImportModalOpen(false)} onImportProjects={async () => {}} />}
                    {view === 'milestones' && <Milestones allMilestones={milestones} allProjects={projects} language={language} onAddMilestones={async (d) => { await apiAddMilestones(d); loadData(); }} onOpenEditModal={setEditingMilestone} onViewMilestoneDetails={setViewingMilestone} onUpdateMilestone={async (id, d) => { await apiUpdateMilestone(id, d); loadData(); }} lookups={lookups} />}
                    {view === 'team' && <Team allUsers={users} allProjects={projects} language={language} />}
                    {view === 'payments' && <Payments allProjects={projects} allMilestones={milestones} allTeams={lookups.teams} language={language} onUpdateMilestone={async (id, d) => { await apiUpdateMilestone(id, d); loadData(); }} />}
                    {view === 'maintenanceContracts' && <MaintenanceContracts contracts={maintenanceContracts} customers={lookups.customers} language={language} onAddContract={async (d) => { await apiAddContract(d); loadData(); }} onUpdateContract={async (id, d) => { await apiUpdateContract(id, d); loadData(); }} />}
                    {view === 'issues' && <Issues allIssues={issues} allProjects={projects} allMilestones={milestones} allUsers={users} language={language} onAddIssue={async (d) => { await apiAddIssue(d); loadData(); }} onUpdateIssue={async (id, d) => { await apiUpdateIssue(id, d); loadData(); }} onAddComment={async (id, uid, c) => { await apiAddIssueComment(id, uid, c); loadData(); }} currentUser={users.find(u => u.id === session.user.id)} />}
                    {view === 'system' && <SystemManagement lookups={lookups} onUpdate={apiUpdateLookups} language={language} onSaveConfig={(k, u) => { localStorage.setItem('supabaseAnonKey', k); localStorage.setItem('supabaseUrl', u); setupClient(k, u); }} />}
                    {view === 'filter' && <MilestoneFilter projects={projects} milestones={milestones} teams={lookups.teams} customers={lookups.customers} projectManagers={lookups.projectManagers} language={language} onUpdateMilestone={async (id, d) => { await apiUpdateMilestone(id, d); loadData(); }} />}
                    {view === 'reports' && <ReportsBuilder projects={projects} milestones={milestones} issues={issues} teams={lookups.teams} language={language} />}
                </main>
            </div>

            {editingProject && <EditProjectModal projectToEdit={editingProject} lookups={lookups} onClose={() => setEditingProject(null)} onUpdateProject={async (id, d) => { await apiUpdateProject(id, d); loadData(); }} language={language} />}
            {editingMilestone && <EditMilestoneModal milestoneToEdit={editingMilestone} allMilestones={milestones} teams={lookups.teams} projects={projects} allMilestoneUpdates={[]} allUsers={users} currentUser={users.find(u => u.id === session.user.id)} onClose={() => setEditingMilestone(null)} onUpdateMilestone={async (id, d) => { await apiUpdateMilestone(id, d); loadData(); }} onAddMilestones={async (d) => { await apiAddMilestones(d); loadData(); }} onAddUpdate={async () => {}} language={language} />}
            {viewingMilestone && <MilestoneDetailModal milestone={viewingMilestone} projects={projects} allMilestoneUpdates={[]} allUsers={users} lookups={lookups} onClose={() => setViewingMilestone(null)} language={language} />}
            {deletingProject && <ConfirmDeleteModal project={deletingProject} onClose={() => setDeletingProject(null)} onConfirm={async () => { await apiDeleteProject(deletingProject.id); setDeletingProject(null); loadData(); }} language={language} />}

            <Chatbot isOpen={isChatbotOpen} onClose={() => setIsChatbotOpen(false)} language={language} projects={projects} milestones={milestones} users={users} lookups={lookups} />
            <button onClick={() => setIsChatbotOpen(true)} className="fixed bottom-6 right-6 bg-slate-900 text-white p-4 rounded-full shadow-xl hover:scale-110 active:scale-95 transition-all z-40"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" viewBox="0 0 20 20" fill="currentColor"><path d="M2 5a2 2 0 012-2h7a2 2 0 012 2v4a2 2 0 01-2 2H9l-3 3v-3H4a2 2 0 01-2-2V5z" /></svg></button>
            <style>{`@keyframes loading { 0% { transform: translateX(-100%); } 100% { transform: translateX(300%); } }`}</style>
        </div>
    );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { Issue, Project, Milestone, User, Language, IssueStatus, IssuePriority, IssueComment } from '../types';
import SearchableSelect from './SearchableSelect';

interface IssuesProps {
    allIssues: Issue[];
    allProjects: Project[];
    allMilestones: Milestone[];
    allUsers: User[];
    language: Language;
    onAddIssue: (data: Omit<Issue, 'id' | 'createdAt'>) => Promise<void>;
    onUpdateIssue: (id: string, data: Partial<Issue>) => Promise<void>;
    onAddComment?: (issueId: string, userId: string, content: string) => Promise<void>;
    currentUser: User | undefined;
}

const Issues: React.FC<IssuesProps> = ({ allIssues, allProjects, allMilestones, allUsers, language, onAddIssue, onUpdateIssue, onAddComment, currentUser }) => {
    const [isAddModalOpen, setIsAddModalOpen] = useState(false);
    const [selectedIssueId, setSelectedIssueId] = useState<string | null>(null);
    const [selectedProjectId, setSelectedProjectId] = useState('all');
    const [selectedStatus, setSelectedStatus] = useState('all');
    const [onlyMyIssues, setOnlyMyIssues] = useState(false);
    const [viewMode, setViewMode] = useState<'grid' | 'grouped'>('grid');

    const t = translations[language];

    const activeViewingIssue = useMemo(() => 
        allIssues.find(i => i.id === selectedIssueId), 
    [allIssues, selectedIssueId]);

    const psUsers = useMemo(() => allUsers.filter(u => u.type === 'PS'), [allUsers]);

    const filteredIssues = useMemo(() => {
        return allIssues.filter(i => {
            const projectMatch = selectedProjectId === 'all' || i.projectId === selectedProjectId;
            const statusMatch = selectedStatus === 'all' || i.status === selectedStatus;
            const userMatch = !onlyMyIssues || (currentUser && i.assigneeId === currentUser.id);
            return projectMatch && statusMatch && userMatch;
        });
    }, [allIssues, selectedProjectId, selectedStatus, onlyMyIssues, currentUser]);

    // Grouping logic for the 'grouped' view
    const groupedIssues = useMemo(() => {
        const groups: Record<string, { project: Project; issues: Issue[] }> = {};

        filteredIssues.forEach(issue => {
            const projId = issue.projectId;
            if (!groups[projId]) {
                const project = allProjects.find(p => p.id === projId) || { id: projId, name: t.unknownProject } as Project;
                groups[projId] = { project, issues: [] };
            }
            groups[projId].issues.push(issue);
        });

        return Object.values(groups).sort((a, b) => a.project.name.localeCompare(b.project.name));
    }, [filteredIssues, allProjects, t.unknownProject]);

    const priorityColors = {
        [IssuePriority.Critical]: 'bg-red-500 text-white shadow-lg shadow-red-500/20',
        [IssuePriority.High]: 'bg-orange-500 text-white shadow-lg shadow-orange-500/20',
        [IssuePriority.Medium]: 'bg-yellow-500 text-slate-900 shadow-lg shadow-yellow-500/10',
        [IssuePriority.Low]: 'bg-blue-400 text-white shadow-lg shadow-blue-400/10',
    };

    const statusColors = {
        [IssueStatus.Open]: 'bg-slate-100 text-slate-700 dark:bg-slate-800 dark:text-slate-300',
        [IssueStatus.InProgress]: 'bg-violet-100 text-violet-700 dark:bg-violet-900/30 dark:text-violet-300',
        [IssueStatus.Resolved]: 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-300',
        [IssueStatus.Closed]: 'bg-slate-200 text-slate-500 dark:bg-slate-700 dark:text-slate-400',
    };

    return (
        <div className="space-y-8 pb-10">
            {/* Main Header */}
            <div className="flex flex-col md:flex-row justify-between items-center gap-4">
                <div>
                    <h1 className="text-4xl font-black text-slate-800 dark:text-white uppercase tracking-tight">{t.title}</h1>
                    <p className="text-slate-400 font-bold text-xs mt-1 uppercase tracking-widest">{t.subtitle}</p>
                </div>
                <div className="flex items-center gap-4">
                    {/* View Switcher */}
                    <div className="flex bg-white dark:bg-slate-900 border border-slate-100 dark:border-slate-800 p-1 rounded-2xl shadow-sm">
                        <button 
                            onClick={() => setViewMode('grid')}
                            className={`p-2.5 rounded-xl transition-all ${viewMode === 'grid' ? 'bg-violet-100 text-violet-600 dark:bg-violet-900/30' : 'text-slate-400 hover:text-slate-600'}`}
                            title={t.gridView}
                        >
                            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path strokeLinecap="round" strokeLinejoin="round" d="M4 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2V6zM14 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2V6zM4 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2v-2zM14 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2v-2z" /></svg>
                        </button>
                        <button 
                            onClick={() => setViewMode('grouped')}
                            className={`p-2.5 rounded-xl transition-all ${viewMode === 'grouped' ? 'bg-violet-100 text-violet-600 dark:bg-violet-900/30' : 'text-slate-400 hover:text-slate-600'}`}
                            title={t.groupedView}
                        >
                            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path strokeLinecap="round" strokeLinejoin="round" d="M4 6h16M4 12h16M4 18h16" /></svg>
                        </button>
                    </div>

                    <button 
                        onClick={() => setOnlyMyIssues(!onlyMyIssues)}
                        className={`px-6 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all border-2 ${onlyMyIssues ? 'bg-violet-600 border-violet-600 text-white shadow-xl shadow-violet-500/20' : 'bg-white border-slate-100 text-slate-500 dark:bg-slate-900 dark:border-slate-800'}`}
                    >
                        {onlyMyIssues ? t.allIssues : t.myIssues}
                    </button>
                    <button onClick={() => setIsAddModalOpen(true)} className="px-8 py-3 bg-violet-600 text-white text-[10px] font-black uppercase tracking-widest rounded-2xl hover:bg-violet-700 shadow-2xl shadow-violet-500/30 flex items-center gap-2 transition-transform active:scale-95">
                        <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="3"><path strokeLinecap="round" strokeLinejoin="round" d="M12 4v16m8-8H4"/></svg>
                        {t.newIssue}
                    </button>
                </div>
            </div>

            {/* Filters Bar */}
            <div className="bg-white/50 dark:bg-slate-900/50 backdrop-blur-md p-4 rounded-[2.5rem] border border-slate-100 dark:border-slate-800 flex flex-wrap gap-4 shadow-sm">
                <div className="flex-1 min-w-[200px]">
                    <SearchableSelect 
                        options={[{value:'all', label:t.allProjects}, ...allProjects.map(p => ({value:p.id, label:p.name}))]} 
                        value={selectedProjectId} 
                        onChange={setSelectedProjectId} 
                        placeholder={t.allProjects} 
                        language={language} 
                    />
                </div>
                <div className="flex-1 min-w-[200px]">
                    <select value={selectedStatus} onChange={e => setSelectedStatus(e.target.value)} className="w-full p-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-xs font-bold outline-none focus:ring-2 focus:ring-violet-500 transition-all">
                        <option value="all">{t.allStatuses}</option>
                        {Object.values(IssueStatus).map(s => <option key={s} value={s}>{s}</option>)}
                    </select>
                </div>
            </div>

            {/* Content Area */}
            {filteredIssues.length > 0 ? (
                viewMode === 'grid' ? (
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                        {filteredIssues.map(issue => (
                            <IssueCard key={issue.id} issue={issue} onClick={() => setSelectedIssueId(issue.id)} currentUser={currentUser} t={t} priorityColors={priorityColors} statusColors={statusColors} />
                        ))}
                    </div>
                ) : (
                    <div className="space-y-12">
                        {groupedIssues.map(group => (
                            <div key={group.project.id} className="animate-in fade-in slide-in-from-top-4 duration-500">
                                <div className="flex items-center justify-between mb-4 pb-2 border-b-2 border-violet-500/20 px-2">
                                    <div className="flex items-center gap-4">
                                        <div className="w-10 h-10 bg-violet-600 rounded-2xl flex items-center justify-center text-white shadow-lg shadow-violet-500/20">
                                            <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path strokeLinecap="round" strokeLinejoin="round" d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" /></svg>
                                        </div>
                                        <div>
                                            <h2 className="text-xl font-black text-slate-800 dark:text-white uppercase tracking-tight">{group.project.name}</h2>
                                            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{group.project.projectCode}</p>
                                        </div>
                                    </div>
                                    <span className="bg-slate-100 dark:bg-slate-800 px-3 py-1 rounded-full text-[10px] font-black text-slate-500 dark:text-slate-400 uppercase">
                                        {group.issues.length} {t.issuesCount}
                                    </span>
                                </div>
                                <div className="space-y-3 ps-2">
                                    {group.issues.map(issue => (
                                        <IssueRow key={issue.id} issue={issue} onClick={() => setSelectedIssueId(issue.id)} currentUser={currentUser} t={t} priorityColors={priorityColors} statusColors={statusColors} />
                                    ))}
                                </div>
                            </div>
                        ))}
                    </div>
                )
            ) : (
                <div className="py-20 text-center text-[11px] font-black uppercase text-slate-300 tracking-[0.5em]">{t.noIssues}</div>
            )}

            {/* Modals */}
            {isAddModalOpen && (
                <AddIssueModal 
                    onClose={() => setIsAddModalOpen(false)} 
                    projects={allProjects} 
                    milestones={allMilestones} 
                    users={psUsers} 
                    language={language} 
                    onSave={async (d) => { 
                        await onAddIssue({...d, reporterId: currentUser?.id || ''}); 
                        setIsAddModalOpen(false); 
                    }}
                />
            )}

            {activeViewingIssue && (
                <IssueDetailModal 
                    issue={activeViewingIssue} 
                    onClose={() => setSelectedIssueId(null)} 
                    language={language} 
                    currentUser={currentUser}
                    onUpdateStatus={async (s) => onUpdateIssue(activeViewingIssue.id, { status: s })}
                    onAddComment={async (c) => { 
                        if (onAddComment && currentUser) {
                            await onAddComment(activeViewingIssue.id, currentUser.id, c);
                        }
                    }}
                />
            )}
        </div>
    );
};

// Sub-components for cleaner code
