        </WidgetWrapper>
    );
};

const AggregatedSummaryWidget: React.FC<{ projectsWithMilestones: any[], projectManagers: User[], language: Language }> = ({ projectsWithMilestones = [], projectManagers = [], language }) => {
    const t = translations[language];
    const [expandedPeriods, setExpandedPeriods] = useState<Record<string, boolean>>({});
    const [searchTerm, setSearchTerm] = useState('');
    const [selectedManagerId, setSelectedManagerId] = useState('all');

    const aggregatedByDate = useMemo(() => {
        const dateGroups = new Map<string, { monthYear: string; sortKey: number; projects: any[] }>();
        projectsWithMilestones.forEach(p => {
            if (!p) return;
            const matchesSearch = !searchTerm || p.name.toLowerCase().includes(searchTerm.toLowerCase());
            const matchesManager = selectedManagerId === 'all' || p.projectManagerId === selectedManagerId;
            if (!matchesSearch || !matchesManager) return;

            (p.milestones || []).forEach((m: any) => {
                if (!m || !m.dueDate) return;
                const date = new Date(m.dueDate);
                if (isNaN(date.getTime())) return;
                const label = `${date.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { month: 'long' })} ${date.getFullYear()}`;
                const sortKey = date.getFullYear() * 100 + date.getMonth();
                if (!dateGroups.has(label)) dateGroups.set(label, { monthYear: label, sortKey, projects: [] });
                const group = dateGroups.get(label)!;
                let projInGroup = group.projects.find(pj => pj.id === p.id);
                if (!projInGroup) {
                    projInGroup = { ...p, milestonesInGroup: [], groupTotal: 0 };
                    group.projects.push(projInGroup);
                }
                projInGroup.milestonesInGroup.push(m);
                if (m.hasPayment) projInGroup.groupTotal += (m.paymentAmount || 0);
            });
        });
        // SORT ASCENDING (Oldest to Newest Groups)
        // Also sort projects inside groups by amount DESC
        const sortedGroups = Array.from(dateGroups.values()).sort((a, b) => a.sortKey - b.sortKey);
        sortedGroups.forEach(g => {
            g.projects.sort((a, b) => b.groupTotal - a.groupTotal);
        });
        return sortedGroups;
    }, [projectsWithMilestones, language, searchTerm, selectedManagerId]);

    const formatCurrency = (val: number) => val.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

    return (
        <WidgetWrapper title={t.executionAggregation} maxHeight="550px">
            <div className="flex flex-col sm:flex-row gap-3 mb-6">
                <div className="flex-1">
                    <input 
                        type="text" 
                        value={searchTerm} 
                        onChange={e => setSearchTerm(e.target.value)} 
                        placeholder={t.quickSearch} 
                        className="w-full p-2.5 text-[10px] font-black uppercase bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-700 rounded-xl outline-none focus:ring-1 focus:ring-violet-500" 
                    />
                </div>
                <div className="flex-1">
                    <SearchableSelect 
                        options={[{value:'all', label:t.allManagers}, ...projectManagers.map(m=>({value:m.id, label:m.name}))]} 
                        value={selectedManagerId} 
                        onChange={setSelectedManagerId} 
                        placeholder={t.allManagers} 
                        language={language}
                    />
                </div>
            </div>
            <div className="space-y-3">
                {aggregatedByDate.map((period, pIdx) => {
                    const isOpen = !!expandedPeriods[period.monthYear];
                    const totalPeriodValue = period.projects.reduce((s, p)=> s + p.groupTotal, 0);
                    return (
                        <div key={pIdx} className="rounded-2xl border border-slate-100 dark:border-slate-800 overflow-hidden shadow-sm">
                            <button onClick={() => setExpandedPeriods(prev => ({...prev, [period.monthYear]: !isOpen}))} className="w-full flex justify-between items-center p-4 bg-white dark:bg-slate-800 hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors">
                                <div className="flex items-center gap-3">
                                    <div className={`p-1.5 rounded-lg transition-transform ${isOpen ? 'rotate-180 bg-violet-600 text-white' : 'bg-slate-100 dark:bg-slate-700 text-slate-400'}`}>
                                        <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="3"><path d="M19 9l-7 7-7-7"/></svg>
                                    </div>
                                    <span className="text-[11px] font-black uppercase tracking-wider">{period.monthYear}</span>
                                </div>
                                <span className="text-[11px] font-black text-emerald-600 dark:text-emerald-400">{formatCurrency(totalPeriodValue)}</span>
                            </button>
                            {isOpen && (
                                <div className="p-3 space-y-2 bg-slate-50/50 dark:bg-slate-900/40 border-t border-slate-100 dark:border-slate-800 animate-in slide-in-from-top-1">
                                    {period.projects.map((proj, prIdx) => (
                                        <div key={prIdx} className="flex justify-between items-center p-3 bg-white dark:bg-slate-800 rounded-xl shadow-xs border border-slate-50 dark:border-slate-700/50">
                                            <div className="min-w-0">
                                                <p className="text-[10px] font-black text-slate-800 dark:text-white truncate uppercase">{proj.name}</p>
                                                <div className="flex items-center gap-1.5 mt-0.5">
                                                    <span className="text-[8px] font-black text-slate-400 uppercase leading-none">{t.manager}:</span>
                                                    <span className="text-[9px] font-bold text-violet-600 dark:text-violet-400 truncate">{proj.projectManager?.name || t.unassigned}</span>
                                                </div>
                                            </div>
                                            <span className="font-bold text-[10px] text-emerald-500 whitespace-nowrap">{formatCurrency(proj.groupTotal)}</span>
                                        </div>
                                    ))}
                                </div>
                            )}
                        </div>
                    );
                })}
                {aggregatedByDate.length === 0 && (
                    <div className="py-20 text-center opacity-20 italic text-[10px] font-black uppercase tracking-widest">{t.noData}</div>
                )}
            </div>
        </WidgetWrapper>
    );
};

