const AnalyticsDashboard: React.FC<any> = ({ projects = [], milestones = [], issues = [], users = [], projectManagers = [], language }) => {
    const t = translations[language];
    const [globalProjectId, setGlobalProjectId] = useState('all');
    const [globalManagerId, setGlobalManagerId] = useState('all');
    const [selectedMonthYear, setSelectedMonthYear] = useState('all');

    const [layout, setLayout] = useState<string[]>(() => {
        const saved = localStorage.getItem('dashboardLayout');
        return saved ? JSON.parse(saved) : WIDGETS_CONFIG.filter(w => w.default).map(w => w.id);
    });
    const [isCustomizeModalOpen, setIsCustomizeModalOpen] = useState(false);

    // Extract unique Month/Year options for the filter
    const monthYearOptions = useMemo(() => {
        const myMap = new Map<string, { label: string, sortKey: number }>();
        milestones.forEach(m => {
            if (!m.dueDate) return;
            const d = new Date(m.dueDate);
            const label = `${d.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { month: 'short' })} ${d.getFullYear()}`;
            const sortKey = d.getFullYear() * 100 + d.getMonth();
            myMap.set(label, { label, sortKey });
        });
        return [{ value: 'all', label: t.allMonths }, ...Array.from(myMap.entries())
            .map(([val, data]) => ({ value: val, label: data.label, sortKey: data.sortKey }))
            .sort((a, b) => a.sortKey - b.sortKey)];
    }, [milestones, language, t.allMonths]);

    const { filteredProjects, filteredMilestones, filteredIssues } = useMemo(() => {
        // Project/Manager basic filtering
        const fps = projects.filter((p: any) => p && 
            (globalProjectId === 'all' || p.id === globalProjectId) && 
            (globalManagerId === 'all' || p.projectManagerId === globalManagerId)
        );

        const pIds = new Set(fps.map((p: any) => p.id));

        // Milestone/Issue filtering including Month/Year
        const fms = milestones.filter((m: any) => {
            if (!m || !pIds.has(m.projectId)) return false;
            if (selectedMonthYear === 'all') return true;
            const d = new Date(m.dueDate!);
            const label = `${d.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { month: 'short' })} ${d.getFullYear()}`;
            return label === selectedMonthYear;
        });

        const fis = issues.filter((i: any) => i && pIds.has(i.projectId));

        return { filteredProjects: fps, filteredMilestones: fms, filteredIssues: fis };
    }, [projects, milestones, issues, globalProjectId, globalManagerId, selectedMonthYear, language]);

    const projectsWithMilestones = useMemo(() => {
        return filteredProjects.map((p: any) => ({ 
            ...p, 
            milestones: filteredMilestones.filter((m: any) => m.projectId === p.id) 
        })).filter((p: any) => p.milestones.length > 0);
    }, [filteredProjects, filteredMilestones]);

    const clearFilters = () => {
        setGlobalProjectId('all');
        setGlobalManagerId('all');
        setSelectedMonthYear('all');
    };

    return (
        <div className="space-y-8 max-w-[1400px] mx-auto pb-20">
            {isCustomizeModalOpen && <CustomizeDashboardModal isOpen={isCustomizeModalOpen} onClose={() => setIsCustomizeModalOpen(false)} currentLayout={layout} onSaveLayout={(l) => { setLayout(l); localStorage.setItem('dashboardLayout', JSON.stringify(l)); setIsCustomizeModalOpen(false); }} language={language} />}
            <div className="flex justify-between items-center">
                <div><h1 className="text-2xl font-black text-slate-800 dark:text-white tracking-tight uppercase">{t.dashboard}</h1><p className="text-slate-400 font-bold text-[10px] mt-1 uppercase tracking-widest">{t.overview}</p></div>
                <button onClick={() => setIsCustomizeModalOpen(true)} className="bg-white dark:bg-slate-800 px-4 py-2 rounded-2xl text-[10px] font-black uppercase tracking-widest text-slate-500 border border-slate-100 shadow-sm">{t.customize}</button>
            </div>
            <div className="bg-slate-50 dark:bg-slate-900/50 p-4 rounded-[2rem] border border-slate-100 flex flex-wrap gap-4 shadow-sm">
                <div className="flex-1 min-w-[180px]"><SearchableSelect options={[{value:'all', label:t.allProjects}, ...projects.map((p: any) => ({value:p.id, label:p.name}))]} value={globalProjectId} onChange={setGlobalProjectId} placeholder={t.allProjects} language={language} /></div>
                <div className="flex-1 min-w-[180px]"><SearchableSelect options={[{value:'all', label:t.allManagers}, ...projectManagers.map((m: any) => ({value:m.id, label:m.name}))]} value={globalManagerId} onChange={setGlobalManagerId} placeholder={t.allManagers} language={language} /></div>
                <div className="flex-1 min-w-[180px]"><SearchableSelect options={monthYearOptions} value={selectedMonthYear} onChange={setSelectedMonthYear} placeholder={t.filterMonthYear} language={language} /></div>
                <button onClick={clearFilters} className="px-5 py-2 bg-slate-800 text-white text-[10px] font-black rounded-xl uppercase tracking-widest hover:bg-black transition-colors">{t.clearFilters}</button>
            </div>
            <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
                {layout.map(id => { 
                    const c = WIDGETS_CONFIG.find(w => w.id === id); 
                    if(!c) return null; 
                    const Comp = c.component as any; 
                    return <div key={id} className={`lg:col-span-${c.colSpan}`}><Comp filteredProjects={filteredProjects} filteredMilestones={filteredMilestones} issues={filteredIssues} users={users} projects={projects} projectsWithMilestones={projectsWithMilestones} projectManagers={projectManagers} language={language} /></div>; 
                })}
            </div>
        </div>
    );
};

export default AnalyticsDashboard;

import React, { useState, useEffect, useMemo } from 'react';
import { Project, Milestone, Language, PaymentStatus, User, MilestoneStatus, Issue, IssueStatus } from '../types';
import StatCard from './StatCard';
import CustomizeDashboardModal from './CustomizeDashboardModal';
import SearchableSelect from './SearchableSelect';

const WidgetWrapper: React.FC<{ title: string, children: React.ReactNode, maxHeight?: string }> = ({ title, children, maxHeight = 'none' }) => (
    <div className="bg-white dark:bg-slate-900 border border-slate-100 dark:border-slate-800 rounded-[2.5rem] flex flex-col overflow-hidden h-full shadow-sm">
        <div className="flex justify-between items-center py-5 px-8 border-b border-slate-50 dark:border-slate-800/50">
            <h2 className="text-[11px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-[0.25em]">{title}</h2>
        </div>
        <div className="flex-grow overflow-y-auto custom-scrollbar px-8 py-6" style={{ maxHeight }}>{children}</div>
