        </WidgetWrapper>
    );
};

const ExecutionPerformanceChartWidget: React.FC<{ filteredMilestones: Milestone[], language: Language }> = ({ filteredMilestones = [], language }) => {
    const t = translations[language];
    const graphData = useMemo(() => {
        const groups = new Map<string, { totalAmount: number; sortKey: number }>();
        filteredMilestones.forEach(m => {
            if (!m || !m.dueDate || !m.hasPayment) return;
            const date = new Date(m.dueDate);
            if (isNaN(date.getTime())) return;
            const monthName = date.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { month: 'short' });
            const year = date.getFullYear();
            const labelKey = `${monthName} ${year}`;
            const sortKey = year * 100 + date.getMonth();
            if (!groups.has(labelKey)) groups.set(labelKey, { totalAmount: 0, sortKey });
            groups.get(labelKey)!.totalAmount += (m.paymentAmount || 0);
        });
        return Array.from(groups.entries())
            .map(([monthYear, data]) => ({ monthYear, ...data }))
            .sort((a, b) => a.sortKey - b.sortKey);
    }, [filteredMilestones, language]);

    const maxAmount = Math.max(...graphData.map(d => d.totalAmount), 1000);
    const yAxisSteps = 5;
    const stepValue = Math.ceil(maxAmount / yAxisSteps / 100) * 100;
    const adjustedMax = stepValue * yAxisSteps;

    const formatCurrencyShort = (val: number) => {
        if (val >= 1000000) return `${(val / 1000000).toFixed(1)}M`;
        if (val >= 1000) return `${(val / 1000).toFixed(1)}K`;
        return val.toString();
    };

    if (graphData.length === 0) return <WidgetWrapper title={t.executionChartTitle}><div className="h-64 flex flex-col items-center justify-center opacity-20"><svg className="w-12 h-12 mb-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="1.5" d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" /></svg></div></WidgetWrapper>;

    return (
        <WidgetWrapper title={t.executionChartTitle}>
            <div className="relative pt-10 pb-6">
                <div className="flex h-72">
                    <div className="flex flex-col justify-between items-end pr-6 text-[10px] font-black text-slate-400 w-16 pb-8">
                        {Array.from({ length: yAxisSteps + 1 }).map((_, i) => (
                            <span key={i}>${formatCurrencyShort(stepValue * (yAxisSteps - i))}</span>
                        ))}
                    </div>
                    <div className="flex-1 relative border-l border-b border-white/20 dark:border-white/5 flex items-end px-4">
                        <div className="absolute inset-0 flex flex-col justify-between pb-8 pointer-events-none">
                            {Array.from({ length: yAxisSteps + 1 }).map((_, i) => (
                                <div key={i} className="w-full border-t border-white/5 dark:border-white/5" />
                            ))}
                        </div>
                        <div className="flex-1 h-full flex items-end justify-around gap-4 z-10">
                            {graphData.map((d, i) => (
                                <div key={i} className="flex-1 flex flex-col items-center justify-end h-full group relative max-w-[60px]">
                                    <div style={{ height: `${(d.totalAmount / adjustedMax) * 100}%` }} className="w-full bg-gradient-to-t from-violet-700 via-indigo-500 to-indigo-400 rounded-t-2xl transition-all duration-1000 shadow-[0_-4px_20px_rgba(99,102,241,0.3)] group-hover:scale-x-110" />
                                    <div className="absolute top-full pt-4 w-full text-center"><span className="text-[9px] font-black text-slate-500 uppercase truncate block tracking-tighter">{d.monthYear}</span></div>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>
            </div>
        </WidgetWrapper>
    );
};

