const StatsOverviewWidget: React.FC<{ filteredProjects: Project[], filteredMilestones: Milestone[], language: Language }> = ({ filteredProjects = [], filteredMilestones = [], language }) => {
    const t = translations[language];
    const stats = useMemo(() => {
        let pendingVal = 0; let sentVal = 0; let paidVal = 0;
        filteredMilestones.forEach(m => {
            if (!m || !m.hasPayment) return;
            const amount = m.paymentAmount || 0;
            const status = m.paymentStatus || PaymentStatus.Pending;
            if (status === PaymentStatus.Pending) pendingVal += amount;
            else if (status === PaymentStatus.Sent) sentVal += amount;
            else if (status === PaymentStatus.Paid) paidVal += amount;
        });
        return { projectsCount: filteredProjects.length, pendingVal, sentVal, paidVal };
    }, [filteredProjects, filteredMilestones]);
    const formatVal = (val: number) => val.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
    return (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
            <StatCard title={t.totalProjects} value={stats.projectsCount.toString()} icon="projects" />
            <StatCard title={t.filteredPending} value={formatVal(stats.pendingVal)} icon="inProgress" trendColor="text-orange-500" />
            <StatCard title={t.filteredSent} value={formatVal(stats.sentVal)} icon="completed" trendColor="text-indigo-500" />
            <StatCard title={t.filteredPaid} value={formatVal(stats.paidVal)} icon="hours" trendColor="text-emerald-500" />
        </div>
    );
};

const AggregatedSummaryWidget: React.FC<{ projectsWithMilestones: any[], projectManagers: User[], language: Language }> = ({ projectsWithMilestones = [], projectManagers = [], language }) => {
    const t = translations[language];
    const [expandedPeriods, setExpandedPeriods] = useState<Record<string, boolean>>({});
    const [searchTerm, setSearchTerm] = useState('');
    const [selectedManagerId, setSelectedManagerId] = useState('all');

    const aggregatedByDate = useMemo(() => {
        const dateGroups = new Map<string, { monthYear: string; sortKey: number; projects: any[] }>();
        projectsWithMilestones.forEach(p => {
            if (!p) return;
            const matchesSearch = !searchTerm || p.name.toLowerCase().includes(searchTerm.toLowerCase());
            const matchesManager = selectedManagerId === 'all' || p.projectManagerId === selectedManagerId;
            if (!matchesSearch || !matchesManager) return;

            (p.milestones || []).forEach((m: any) => {
                if (!m || !m.dueDate) return;
                const date = new Date(m.dueDate);
                if (isNaN(date.getTime())) return;
                const label = `${date.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { month: 'long' })} ${date.getFullYear()}`;
                const sortKey = date.getFullYear() * 100 + date.getMonth();
                if (!dateGroups.has(label)) dateGroups.set(label, { monthYear: label, sortKey, projects: [] });
                const group = dateGroups.get(label)!;
                let projInGroup = group.projects.find(pj => pj.id === p.id);
                if (!projInGroup) {
                    projInGroup = { ...p, milestonesInGroup: [], groupTotal: 0 };
                    group.projects.push(projInGroup);
                }
                projInGroup.milestonesInGroup.push(m);
                if (m.hasPayment) projInGroup.groupTotal += (m.paymentAmount || 0);
            });
        });
        const sortedGroups = Array.from(dateGroups.values()).sort((a, b) => a.sortKey - b.sortKey);
        sortedGroups.forEach(g => {
            g.projects.sort((a, b) => b.groupTotal - a.groupTotal);
        });
        return sortedGroups;
    }, [projectsWithMilestones, language, searchTerm, selectedManagerId]);

    const formatCurrency = (val: number) => val.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

    return (
        <WidgetWrapper title={t.executionAggregation} maxHeight="600px">
            <div className="flex flex-col sm:flex-row gap-4 mb-8">
                <div className="flex-1">
                    <input 
                        type="text" 
                        value={searchTerm} 
                        onChange={e => setSearchTerm(e.target.value)} 
                        placeholder={t.quickSearch} 
                        className="w-full px-5 py-3.5 text-[11px] font-black uppercase bg-white/50 dark:bg-slate-800/50 border border-white/20 dark:border-white/5 rounded-2xl outline-none focus:ring-2 focus:ring-violet-500/50 transition-all placeholder:text-slate-400" 
                    />
                </div>
                <div className="flex-1">
                    <SearchableSelect 
                        options={[{value:'all', label:t.allManagers}, ...projectManagers.map(m=>({value:m.id, label:m.name}))]} 
                        value={selectedManagerId} 
                        onChange={setSelectedManagerId} 
                        placeholder={t.allManagers} 
                        language={language}
                    />
                </div>
            </div>
            <div className="space-y-4">
                {aggregatedByDate.map((period, pIdx) => {
                    const isOpen = !!expandedPeriods[period.monthYear];
                    const totalPeriodValue = period.projects.reduce((s, p)=> s + p.groupTotal, 0);
                    return (
                        <div key={pIdx} className="rounded-[2rem] border border-white/20 dark:border-white/5 overflow-hidden transition-all duration-300">
                            <button onClick={() => setExpandedPeriods(prev => ({...prev, [period.monthYear]: !isOpen}))} className="w-full flex justify-between items-center p-6 bg-white/40 dark:bg-slate-800/40 hover:bg-white/60 dark:hover:bg-slate-800/60 transition-colors">
                                <div className="flex items-center gap-4">
                                    <div className={`w-8 h-8 rounded-xl flex items-center justify-center transition-all ${isOpen ? 'rotate-180 bg-violet-600 text-white shadow-lg' : 'bg-white/50 dark:bg-slate-700 text-slate-400'}`}>
                                        <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="3"><path d="M19 9l-7 7-7-7"/></svg>
                                    </div>
                                    <span className="text-[12px] font-black uppercase tracking-widest text-slate-700 dark:text-slate-200">{period.monthYear}</span>
                                </div>
                                <span className="text-[14px] font-black text-emerald-600 dark:text-emerald-400">{formatCurrency(totalPeriodValue)}</span>
                            </button>
                            {isOpen && (
                                <div className="p-4 space-y-3 bg-white/20 dark:bg-black/20 border-t border-white/10 dark:border-white/5 animate-in slide-in-from-top-2">
                                    {period.projects.map((proj, prIdx) => (
                                        <div key={prIdx} className="flex justify-between items-center p-5 bg-white/60 dark:bg-slate-800/80 rounded-[1.5rem] shadow-sm border border-white/30 dark:border-white/5 group hover:border-violet-400/50 transition-all">
                                            <div className="min-w-0">
                                                <p className="text-[11px] font-black text-slate-800 dark:text-white truncate uppercase group-hover:text-violet-600 transition-colors">{proj.name}</p>
                                                <div className="flex items-center gap-2 mt-1.5">
                                                    <div className="w-5 h-5 rounded-full bg-violet-100 dark:bg-violet-900/30 flex items-center justify-center text-[8px] text-violet-600">👤</div>
                                                    <span className="text-[9px] font-bold text-slate-400 dark:text-slate-500 uppercase">{t.manager}:</span>
                                                    <span className="text-[9px] font-black text-violet-600/70 dark:text-violet-400/70 truncate">{proj.projectManager?.name || t.unassigned}</span>
                                                </div>
                                            </div>
                                            <div className="text-right">
                                                <span className="font-black text-[11px] text-slate-800 dark:text-white block">{formatCurrency(proj.groupTotal)}</span>
                                                <span className="text-[8px] font-black text-slate-400 uppercase">{proj.progress}% {t.progress}</span>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            )}
                        </div>
                    );
                })}
                {aggregatedByDate.length === 0 && (
                    <div className="py-24 text-center opacity-30 italic text-[11px] font-black uppercase tracking-[0.4em]">{t.noData}</div>
                )}
            </div>
        </WidgetWrapper>
    );
};

const ResourceIssuesWidget: React.FC<{ users: User[], issues: Issue[], language: Language }> = ({ users, issues, language }) => {
    const t = translations[language];
    const [searchQuery, setSearchQuery] = useState('');

    const workload = useMemo(() => {
        return users.map(u => {
            const userIssues = issues.filter(i => i.assigneeId === u.id);
            const openIssues = userIssues.filter(i => i.status === IssueStatus.Open || i.status === IssueStatus.InProgress);
            const projectCounts: Record<string, { name: string, count: number }> = {};
            openIssues.forEach(iss => {
                const pName = iss.project?.name || t.unknownProject;
                if (!projectCounts[pName]) projectCounts[pName] = { name: pName, count: 0 };
                projectCounts[pName].count++;
            });
            return { 
                user: u, 
                total: userIssues.length, 
                open: openIssues.length,
                projects: Object.values(projectCounts).sort((a, b) => b.count - a.count)
            };
        })
        .filter(w => w.total > 0)
        .filter(w => {
            if (!searchQuery) return true;
            const searchLower = searchQuery.toLowerCase();
            const nameMatch = w.user.name.toLowerCase().includes(searchLower);
            const projectMatch = w.projects.some(p => p.name.toLowerCase().includes(searchLower));
            return nameMatch || projectMatch;
        })
        .sort((a, b) => b.open - a.open);
    }, [users, issues, t.unknownProject, searchQuery]);

    return (
        <WidgetWrapper title={t.resourceIssuesTitle} maxHeight="600px">
            <div className="mb-8 relative group">
                <span className="absolute inset-y-0 left-5 flex items-center pointer-events-none text-slate-400 group-focus-within:text-violet-500 transition-colors">
                    <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="3"><path strokeLinecap="round" strokeLinejoin="round" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
                </span>
                <input 
                    type="text" 
                    value={searchQuery} 
                    onChange={e => setSearchQuery(e.target.value)} 
                    placeholder={t.searchResources} 
                    className="w-full pl-12 pr-5 py-3.5 text-[11px] font-black uppercase bg-white/50 dark:bg-slate-800/50 border border-white/20 dark:border-white/5 rounded-[1.5rem] outline-none focus:ring-2 focus:ring-violet-500/50 transition-all placeholder:text-slate-400 shadow-sm" 
                />
            </div>
            <div className="space-y-6">
                {workload.length > 0 ? workload.map((w, i) => (
                    <div key={i} className="p-6 bg-white/40 dark:bg-slate-800/40 rounded-[2.5rem] border border-white/30 dark:border-white/5 shadow-sm hover:shadow-md transition-all animate-in fade-in slide-in-from-bottom-2">
                        <div className="flex items-center justify-between mb-6">
                            <div className="flex items-center gap-5">
                                <div className="relative group">
                                    <img src={w.user.avatarUrl || `https://ui-avatars.com/api/?name=${w.user.name}&background=8b5cf6&color=fff`} className="w-14 h-14 rounded-[1.25rem] border-2 border-white dark:border-slate-800 shadow-xl group-hover:scale-105 transition-transform" />
                                    <div className={`absolute -top-2 -right-2 w-7 h-7 rounded-full flex items-center justify-center border-4 border-white dark:border-slate-900 shadow-lg font-black text-[10px] ${w.open > 3 ? 'bg-red-500 text-white' : 'bg-emerald-500 text-white'}`}>
                                        {w.open}
                                    </div>
                                </div>
                                <div>
                                    <p className="text-[13px] font-black text-slate-800 dark:text-white leading-tight uppercase tracking-tight">{w.user.name}</p>
                                    <p className="text-[9px] font-black text-violet-500/70 dark:text-violet-400/70 uppercase tracking-[0.2em] mt-1">{w.user.type || 'Staff'}</p>
                                </div>
                            </div>
                            <div className="text-end">
                                <span className={`text-2xl font-black ${w.open > 5 ? 'text-red-500' : 'text-indigo-600 dark:text-indigo-400'}`}>{w.open}</span>
                                <span className="text-[8px] font-black text-slate-400 uppercase block tracking-widest">{t.openIssues}</span>
                            </div>
                        </div>

                        {w.projects.length > 0 && (
                            <div className="flex flex-wrap gap-2 pt-4 border-t border-white/10 dark:border-white/5">
                                {w.projects.map((p, pIdx) => (
                                    <div key={pIdx} className="px-3 py-1.5 bg-white/80 dark:bg-slate-900/80 border border-white/50 dark:border-white/5 rounded-xl flex items-center gap-2 shadow-sm">
                                        <span className="text-[9px] font-black text-slate-600 dark:text-slate-300 truncate max-w-[100px] uppercase">{p.name}</span>
                                        <span className="text-[10px] font-black text-violet-600 bg-violet-100 dark:bg-violet-900/50 px-1.5 rounded-md">{p.count}</span>
                                    </div>
                                ))}
