const Sidebar: React.FC<SidebarProps> = ({ currentView, setCurrentView, language, allowedViews }) => {
  const translations = {
    ar: { dashboard: 'لوحة التحكم', filter: 'الفلترة', projects: 'المشاريع', milestones: 'المعالم', team: 'المدراء', payments: 'المدفوعات', maintenanceContracts: 'الصيانة', issues: 'الأعطال', system: 'الإدارة', reports: 'التقارير' },
    en: { dashboard: 'Dashboard', filter: 'Filter', projects: 'Projects', milestones: 'Milestones', team: 'PMs', payments: 'Payments', maintenanceContracts: 'Maintenance', issues: 'Issues', system: 'System', reports: 'Reports' },
  };
  const t = translations[language];
  const allNavItems: { view: View; label: string }[] = [
    { view: 'dashboard', label: t.dashboard },
    { view: 'filter', label: t.filter },
    { view: 'projects', label: t.projects },
    { view: 'milestones', label: t.milestones },
    { view: 'issues', label: t.issues },
    { view: 'team', label: t.team },
    { view: 'payments', label: t.payments },
    { view: 'reports', label: t.reports },
    { view: 'maintenanceContracts', label: t.maintenanceContracts },
    { view: 'system', label: t.system },
  ];

  // Filter navigation items based on allowedViews
  const navItems = allNavItems.filter(item => allowedViews.includes(item.view));

  return (
    <aside className="w-64 flex-shrink-0 bg-white/80 dark:bg-indigo-950/20 backdrop-blur-2xl border-r border-white/20 dark:border-white/5 flex flex-col m-4 rounded-[2.5rem] shadow-2xl overflow-hidden" dir={language === 'ar' ? 'rtl' : 'ltr'}>
      <div className="h-28 flex items-center justify-center px-8 border-b border-white/20 dark:border-white/5">
