                />
            </div>
            <div className="space-y-6">
                {workload.length > 0 ? workload.map((w, i) => (
                    <div key={i} className="p-6 bg-white/40 dark:bg-slate-800/40 rounded-[2.5rem] border border-white/30 dark:border-white/5 shadow-sm hover:shadow-xl hover:scale-[1.01] transition-all duration-300 animate-in fade-in slide-in-from-bottom-2">
                        <div className="flex items-center justify-between mb-6">
                            <div className="flex items-center gap-5">
                                <div className="relative group/avatar">
                                    <img src={w.user.avatarUrl || `https://ui-avatars.com/api/?name=${w.user.name}&background=8b5cf6&color=fff`} className="w-16 h-16 rounded-[1.5rem] border-2 border-white dark:border-slate-800 shadow-xl group-hover/avatar:rotate-3 transition-transform" />
                                    <div className={`absolute -top-3 -right-3 w-8 h-8 rounded-full flex items-center justify-center border-4 border-white dark:border-slate-900 shadow-lg font-black text-[12px] ${w.open > 3 ? 'bg-red-500 text-white' : 'bg-emerald-500 text-white'}`}>
                                        {w.open}
                                    </div>
                                </div>
                                <div>
                                    <p className="text-[15px] font-black text-slate-800 dark:text-white leading-tight uppercase tracking-tight">{w.user.name}</p>
                                    <p className="text-[10px] font-black text-violet-500 uppercase tracking-[0.2em] mt-1">{w.user.type || 'Staff'}</p>
