const ExecutionPerformanceChartWidget: React.FC<{ filteredMilestones: Milestone[], language: Language }> = ({ filteredMilestones = [], language }) => {
    const t = translations[language];
    const graphData = useMemo(() => {
        const groups = new Map<string, { totalAmount: number; sortKey: number }>();
        filteredMilestones.forEach(m => {
            if (!m || !m.dueDate || !m.hasPayment) return;
            const date = new Date(m.dueDate);
            if (isNaN(date.getTime())) return;
            const labelKey = `${date.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { month: 'short' })} ${date.getFullYear()}`;
            const sortKey = date.getFullYear() * 100 + date.getMonth();
            if (!groups.has(labelKey)) groups.set(labelKey, { totalAmount: 0, sortKey });
            groups.get(labelKey)!.totalAmount += (m.paymentAmount || 0);
        });
        return Array.from(groups.entries()).map(([monthYear, data]) => ({ monthYear, ...data })).sort((a, b) => a.sortKey - b.sortKey);
    }, [filteredMilestones, language]);

    const maxAmount = Math.max(...graphData.map(d => d.totalAmount), 1000);
    const formatCurrencyShort = (val: number) => val >= 1000000 ? `${(val/1000000).toFixed(1)}M` : val >= 1000 ? `${(val/1000).toFixed(1)}K` : val.toString();

    return (
        <WidgetWrapper title={t.executionChartTitle}>
            <div className="relative pt-12 pb-8 h-80 flex items-end">
                <div className="flex-1 h-full flex items-end justify-around gap-6 z-10 px-4">
                    {graphData.map((d, i) => (
                        <div key={i} className="flex-1 flex flex-col items-center justify-end h-full group relative max-w-[80px]">
                            <div className="absolute bottom-full mb-4 opacity-0 group-hover:opacity-100 transition-all scale-75 group-hover:scale-100 bg-slate-900 text-white text-[10px] font-black px-3 py-1.5 rounded-xl z-20 shadow-2xl whitespace-nowrap">
                                ${d.totalAmount.toLocaleString()}
                            </div>
                            <div style={{ height: `${(d.totalAmount / maxAmount) * 100}%` }} className="w-full bg-gradient-to-t from-violet-700 via-indigo-500 to-indigo-400 rounded-t-[1.5rem] transition-all duration-1000 shadow-[0_-4px_20px_rgba(99,102,241,0.3)] group-hover:shadow-[0_-4px_30px_rgba(99,102,241,0.5)] group-hover:scale-x-110" />
                            <div className="absolute top-full pt-6 w-full text-center">
                                <span className="text-[10px] font-black text-slate-500 uppercase truncate block tracking-tighter">{d.monthYear}</span>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        </WidgetWrapper>
    );
};

