const AnalyticsDashboard: React.FC<any> = ({ projects = [], milestones = [], issues = [], users = [], projectManagers = [], language }) => {
    const t = translations[language];
    const [globalProjectId, setGlobalProjectId] = useState('all');
    const [globalManagerId, setGlobalManagerId] = useState('all');
    const [selectedMonthYear, setSelectedMonthYear] = useState('all');
    const [layout, setLayout] = useState<string[]>(() => {
        const saved = localStorage.getItem('dashboardLayout');
        return saved ? JSON.parse(saved) : WIDGETS_CONFIG.filter(w => w.default).map(w => w.id);
    });
    const [isCustomizeModalOpen, setIsCustomizeModalOpen] = useState(false);

    const monthYearOptions = useMemo(() => {
        const myMap = new Map<string, { label: string, sortKey: number }>();
        milestones.forEach(m => {
            if (!m.dueDate) return;
            const d = new Date(m.dueDate);
            const label = `${d.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { month: 'short' })} ${d.getFullYear()}`;
            const sortKey = d.getFullYear() * 100 + d.getMonth();
            myMap.set(label, { label, sortKey });
        });
        return [{ value: 'all', label: t.allMonths }, ...Array.from(myMap.entries())
            .map(([val, data]) => ({ value: val, label: data.label, sortKey: data.sortKey }))
            .sort((a, b) => a.sortKey - b.sortKey)];
    }, [milestones, language, t.allMonths]);

    const { filteredProjects, filteredMilestones, filteredIssues } = useMemo(() => {
        const fps = projects.filter((p: any) => p && (globalProjectId === 'all' || p.id === globalProjectId) && (globalManagerId === 'all' || p.projectManagerId === globalManagerId));
        const pIds = new Set(fps.map((p: any) => p.id));
        const fms = milestones.filter((m: any) => {
            if (!m || !pIds.has(m.projectId)) return false;
            if (selectedMonthYear === 'all') return true;
            const d = new Date(m.dueDate!);
            const label = `${d.toLocaleString(language === 'ar' ? 'ar-EG' : 'en-US', { month: 'short' })} ${d.getFullYear()}`;
            return label === selectedMonthYear;
        });
        const fis = issues.filter((i: any) => i && pIds.has(i.projectId));
        return { filteredProjects: fps, filteredMilestones: fms, filteredIssues: fis };
    }, [projects, milestones, issues, globalProjectId, globalManagerId, selectedMonthYear, language]);

    const projectsWithMilestones = useMemo(() => {
        return filteredProjects.map((p: any) => ({ ...p, milestones: filteredMilestones.filter((m: any) => m.projectId === p.id) })).filter((p: any) => p.milestones.length > 0);
    }, [filteredProjects, filteredMilestones]);

    return (
        <div className="space-y-12 max-w-[1600px] mx-auto pb-24">
            {isCustomizeModalOpen && <CustomizeDashboardModal isOpen={isCustomizeModalOpen} onClose={() => setIsCustomizeModalOpen(false)} currentLayout={layout} onSaveLayout={(l) => { setLayout(l); localStorage.setItem('dashboardLayout', JSON.stringify(l)); setIsCustomizeModalOpen(false); }} language={language} />}
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-8 px-2">
                <div>
                    <h1 className="text-5xl font-black text-slate-800 dark:text-white tracking-tighter uppercase">{t.dashboard}</h1>
                    <p className="text-slate-400 font-black text-[12px] mt-3 uppercase tracking-[0.4em]">{t.overview}</p>
                </div>
                <button onClick={() => setIsCustomizeModalOpen(true)} className="glass-card px-10 py-4 rounded-2xl text-[11px] font-black uppercase tracking-widest text-violet-600 dark:text-violet-400 shadow-2xl hover:scale-105 transition-all border border-white/20">{t.customize}</button>
            </div>
            <div className="glass-card p-8 rounded-[3rem] flex flex-wrap gap-8 shadow-2xl border border-white/20 dark:border-white/5">
                <div className="flex-1 min-w-[250px]"><SearchableSelect options={[{value:'all', label:t.allProjects}, ...projects.map((p: any) => ({value:p.id, label:p.name}))]} value={globalProjectId} onChange={setGlobalProjectId} placeholder={t.allProjects} language={language} /></div>
                <div className="flex-1 min-w-[250px]"><SearchableSelect options={[{value:'all', label:t.allManagers}, ...projectManagers.map(m=>({value:m.id, label:m.name}))]} value={globalManagerId} onChange={setGlobalManagerId} placeholder={t.allManagers} language={language} /></div>
                <div className="flex-1 min-w-[250px]"><SearchableSelect options={monthYearOptions} value={selectedMonthYear} onChange={setSelectedMonthYear} placeholder={t.filterMonthYear} language={language} /></div>
                <button onClick={() => { setGlobalProjectId('all'); setGlobalManagerId('all'); setSelectedMonthYear('all'); }} className="px-12 py-4 bg-slate-900 dark:bg-slate-800 text-white text-[11px] font-black rounded-2xl uppercase tracking-widest hover:bg-black transition-all shadow-xl">{t.clearFilters}</button>
            </div>
            <div className="grid grid-cols-1 lg:grid-cols-4 gap-10">
                {layout.map(id => { 
                    const c = WIDGETS_CONFIG.find(w => w.id === id); 
                    if(!c) return null; 
                    const Comp = c.component as any; 
                    return <div key={id} className={`lg:col-span-${c.colSpan}`}><Comp filteredProjects={filteredProjects} filteredMilestones={filteredMilestones} issues={filteredIssues} users={users} projects={projects} projectsWithMilestones={projectsWithMilestones} projectManagers={projectManagers} language={language} /></div>; 
                })}
            </div>
        </div>
    );
};

export default AnalyticsDashboard;

