interface SystemManagementProps {
    lookups: Lookups;
    onUpdate: (lookupType: keyof Lookups, newLookups: Lookup[]) => void;
    language: Language;
    onSaveConfig: (supabaseKey: string, supabaseUrl: string) => void;
    isSetupMode?: boolean;
    rolePermissions: RolePermissions[];
    onUpdatePermissions: (newPermissions: RolePermissions[]) => void;
}

const SystemManagement: React.FC<SystemManagementProps> = ({ lookups, onUpdate, language, onSaveConfig, isSetupMode = false, rolePermissions, onUpdatePermissions }) => {
    const [supabaseKey, setSupabaseKey] = useState('');
    const [supabaseUrl, setSupabaseUrl] = useState('https://dcamlinhazzmbaldsrdo.supabase.co');
    const [activeTab, setActiveTab] = useState<'users' | 'permissions' | 'lookups' | 'config'>('users');
    const [users, setUsers] = useState<User[]>([]);
    const [isLoadingUsers, setIsLoadingUsers] = useState(false);

    useEffect(() => {
        if (!isSetupMode) {
            setSupabaseKey(localStorage.getItem('supabaseAnonKey') || '');
            setSupabaseUrl(localStorage.getItem('supabaseUrl') || 'https://dcamlinhazzmbaldsrdo.supabase.co');
            fetchUsers();
        }
    }, [isSetupMode]);

    const fetchUsers = async () => {
        const sb = getSupabase();
        if (!sb) return;
        setIsLoadingUsers(true);
        try {
            const { data } = await sb.from('users').select('*');
            if (data) setUsers(data.map(u => ({ id: u.id, name: u.name, type: u.type, avatarUrl: u.avatar_url })));
        } finally {
            setIsLoadingUsers(false);
        }
    };

    const updateUserRole = async (userId: string, newType: string) => {
        const sb = getSupabase();
        if (!sb) return;
        const { error } = await sb.from('users').update({ type: newType }).eq('id', userId);
        if (!error) fetchUsers();
    };

    const translations = {
        ar: {
            title: "إدارة النظام", subtitle: "تعديل المستخدمين، الصلاحيات، وإعدادات الربط.",
