                                    <th className="px-6 py-4 text-xs font-black text-slate-400 uppercase text-end">{t.actions}</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-100">
                                {users.map(user => (
                                    <tr key={user.id} className="hover:bg-slate-50/50 transition-colors">
                                        <td className="px-6 py-4 flex items-center gap-4">
                                            <img src={user.avatarUrl || `https://ui-avatars.com/api/?name=${user.name}&background=8b5cf6&color=fff`} className="w-10 h-10 rounded-full border border-slate-200" />
                                            <div>
                                                <p className="text-sm font-bold text-slate-800">{user.name}</p>
                                                <p className="text-[10px] text-slate-400 font-mono">ID: {user.id.substring(0,8)}</p>
                                            </div>
                                        </td>
                                        <td className="px-6 py-4">
                                            <select 
                                                value={user.type || 'Staff'} 
                                                onChange={(e) => updateUserRole(user.id, e.target.value)}
                                                className="bg-white border border-slate-200 rounded-lg px-3 py-1.5 text-xs font-bold text-slate-700 outline-none focus:ring-1 focus:ring-violet-500"
                                            >
                                                <option value="PM">Project Manager (PM)</option>
                                                <option value="PS">Pro Services (PS)</option>
                                                <option value="Staff">Staff</option>
                                                <option value="Client">Client</option>
                                            </select>
                                        </td>
                                        <td className="px-6 py-4 text-end">
                                            <button className="text-red-500 text-xs font-bold hover:underline">Revoke Access</button>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </div>
            )}

            {activeTab === 'permissions' && (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    {rolePermissions.map(rolePerm => (
                        <div key={rolePerm.role} className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 p-8 rounded-3xl shadow-sm">
                            <div className="flex items-center gap-4 mb-8">
                                <div className="w-12 h-12 bg-violet-600 rounded-2xl flex items-center justify-center text-white shadow-lg">
                                    <span className="font-black">{rolePerm.role}</span>
                                </div>
                                <div>
                                    <h3 className="font-black text-slate-800 dark:text-white uppercase">{rolePerm.role} Profile</h3>
                                    <p className="text-xs text-slate-400 font-bold">{rolePerm.allowedViews.length} modules active</p>
                                </div>
                            </div>
                            <div className="grid grid-cols-2 gap-2">
                                {allAvailableViews.map(viewDef => {
                                    const allowed = rolePerm.allowedViews.includes(viewDef.id);
                                    return (
                                        <button 
                                            key={viewDef.id} 
                                            onClick={() => togglePermission(rolePerm.role, viewDef.id)}
                                            className={`flex items-center gap-3 p-3 rounded-xl border-2 transition-all ${allowed ? 'bg-violet-50 border-violet-600 text-violet-700' : 'bg-white border-slate-100 text-slate-400 hover:border-slate-200'}`}
                                        >
                                            <div className={`w-2.5 h-2.5 rounded-full ${allowed ? 'bg-violet-600' : 'bg-slate-200'}`}></div>
                                            <span className="text-[10px] font-black uppercase tracking-wider">{viewDef.label}</span>
                                        </button>
                                    );
                                })}
                            </div>
                        </div>
                    ))}
                </div>
            )}

            {activeTab === 'lookups' && (
                <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
                    <LookupEditor title="Countries" initialValues={lookups.countries} onSave={(v) => onUpdate('countries', v as Lookup[])} language={language} />
                    <LookupEditor title="Categories" initialValues={lookups.categories} onSave={(v) => onUpdate('categories', v as Lookup[])} language={language} />
                    <LookupEditor title="Teams" initialValues={lookups.teams} onSave={(v) => onUpdate('teams', v as Lookup[])} language={language} />
                </div>
            )}

            {activeTab === 'config' && (
                <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 p-10 rounded-3xl shadow-sm max-w-2xl mx-auto">
                    <h2 className="text-2xl font-black text-slate-800 mb-8">{t.configTitle}</h2>
                    <div className="space-y-6">
                        <div>
                            <label className="block text-xs font-black text-slate-400 uppercase mb-2 ps-1">Supabase Base URL</label>
                            <input type="text" value={supabaseUrl} onChange={e => setSupabaseUrl(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl p-4 text-sm font-bold outline-none focus:ring-2 focus:ring-violet-600 transition-all" />
                        </div>
                        <div>
                            <label className="block text-xs font-black text-slate-400 uppercase mb-2 ps-1">Supabase Anon Key</label>
                            <input type="password" value={supabaseKey} onChange={e => setSupabaseKey(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl p-4 text-sm font-bold outline-none focus:ring-2 focus:ring-violet-600 transition-all" />
                        </div>
                        <button onClick={() => onSaveConfig(supabaseKey, supabaseUrl)} className="w-full py-4 bg-violet-600 text-white rounded-xl text-xs font-black uppercase tracking-widest hover:bg-violet-700 transition-all shadow-lg shadow-violet-500/20">{t.save}</button>
                    </div>
                </div>
            )}
        </div>
    );
};

export default SystemManagement;

import React, { useState, useEffect, useCallback, useRef, useMemo } from 'react';
import { Session, SupabaseClient } from '@supabase/supabase-js';
import Sidebar from './components/Sidebar';
import Header from './components/Header';
import AnalyticsDashboard from './components/AnalyticsDashboard';
import Projects from './components/Projects';
import Milestones from './components/Milestones';
import Team from './components/Team';
import Payments from './components/Payments';
import MaintenanceContracts from './components/MaintenanceContracts';
import Issues from './components/Issues';
import SystemManagement from './components/SystemManagement';
import MilestoneFilter from './components/MilestoneFilter';
import ReportsBuilder from './components/ReportsBuilder';
import Login from './components/Login';
import EditProjectModal from './components/EditProjectModal';
import EditMilestoneModal from './components/EditMilestoneModal';
import MilestoneDetailModal from './components/MilestoneDetailModal';
import ConfirmDeleteModal from './components/ConfirmDeleteModal';
import SearchResultModal from './components/SearchResultModal';
import Chatbot from './components/Chatbot';
import { Language, Theme, View, Project, Milestone, User, Lookups, MaintenanceContract, Issue, Notification, RolePermissions, AnalysisResult } from './types';
import { 
    fetchAllData, 
    addProject as apiAddProject, 
    updateProject as apiUpdateProject, 
    addMilestones as apiAddMilestones, 
    updateMilestone as apiUpdateMilestone, 
    updateLookups as apiUpdateLookups, 
    deleteProject as apiDeleteProject,
    addMaintenanceContract as apiAddContract,
    updateMaintenanceContract as apiUpdateContract,
    addIssue as apiAddIssue,
    updateIssue as apiUpdateIssue,
    addIssueComment as apiAddIssueComment,
} from './services/api';
import { initSupabase, getSupabase } from './services/supabaseClient';
import { analyzeQuery } from './services/geminiService';

const App: React.FC = () => {
    const [view, setView] = useState<View>(() => (localStorage.getItem('lastView') as View) || 'dashboard');
    const [language, setLanguage] = useState<Language>(() => (localStorage.getItem('language') as Language) || 'ar');
    const [theme, setTheme] = useState<Theme>(() => (localStorage.getItem('theme') as Theme) || 'light');
    const [isLoading, setIsLoading] = useState(true);
    const [errorMsg, setErrorMsg] = useState<string | null>(null);
    const [isSidebarOpen, setIsSidebarOpen] = useState(false);

    const [projects, setProjects] = useState<Project[]>([]);
    const [milestones, setMilestones] = useState<Milestone[]>([]);
    const [maintenanceContracts, setMaintenanceContracts] = useState<MaintenanceContract[]>([]);
    const [issues, setIssues] = useState<Issue[]>([]);
    const [notifications, setNotifications] = useState<Notification[]>([]);
    const [users, setUsers] = useState<User[]>([]);
    const [lookups, setLookups] = useState<Lookups>({ countries: [], categories: [], teams: [], products: [], projectStatuses: [], projectManagers: [], customers: [] });

    const [rolePermissions, setRolePermissions] = useState<RolePermissions[]>(() => {
        const saved = localStorage.getItem('rolePermissions');
        return saved ? JSON.parse(saved) : [
            { role: 'PM', allowedViews: ['dashboard', 'filter', 'projects', 'milestones', 'team', 'payments', 'reports', 'maintenanceContracts', 'system', 'issues'] },
            { role: 'PS', allowedViews: ['dashboard', 'issues', 'reports'] },
            { role: 'Staff', allowedViews: ['dashboard', 'projects', 'issues'] },
            { role: 'Client', allowedViews: ['dashboard'] }
        ];
    });

    const [editingProject, setEditingProject] = useState<Project | null>(null);
    const [editingMilestone, setEditingMilestone] = useState<Milestone | null>(null);
    const [viewingMilestone, setViewingMilestone] = useState<Milestone | null>(null);
    const [deletingProject, setDeletingProject] = useState<Project | null>(null);
    const [isChatbotOpen, setIsChatbotOpen] = useState(false);
    const [isImportModalOpen, setIsImportModalOpen] = useState(false);
    const [isAnalyzing, setIsAnalyzing] = useState(false);
    const [searchResult, setSearchResult] = useState<AnalysisResult | null>(null);

    const [session, setSession] = useState<Session | null>(null);
    const [supabaseClient, setSupabaseClient] = useState<SupabaseClient | null>(null);
    const [isAppConfigured, setIsAppConfigured] = useState(false);

    const isFetching = useRef(false);

    const currentUser = useMemo(() => users.find(u => u.id === session?.user?.id), [users, session]);

    const allowedViews = useMemo(() => {
        if (!currentUser) return [];
        const config = rolePermissions.find(p => p.role === currentUser.type);
        return config ? config.allowedViews : [];
    }, [currentUser, rolePermissions]);

    useEffect(() => {
        if (currentUser && allowedViews.length > 0 && !allowedViews.includes(view)) {
            setView(allowedViews[0]);
        }
    }, [view, allowedViews, currentUser]);

    useEffect(() => { localStorage.setItem('lastView', view); }, [view]);
    useEffect(() => { localStorage.setItem('language', language); }, [language]);
    useEffect(() => {
        localStorage.setItem('theme', theme);
        document.documentElement.classList.toggle('dark', theme === 'dark' || (theme === 'system' && window.matchMedia('(prefers-color-scheme: dark)').matches));
    }, [theme]);

    const setupClient = useCallback((key: string, url: string) => {
        try {
            const client = initSupabase(url, key);
            setSupabaseClient(client);
            setIsAppConfigured(true);
            setErrorMsg(null);
            return true;
        } catch (e: any) {
            setErrorMsg(e.message || "Invalid Supabase Configuration");
            setIsAppConfigured(false);
            return false;
        }
    }, []);

    useEffect(() => {
        const key = localStorage.getItem('supabaseAnonKey');
        const url = localStorage.getItem('supabaseUrl') || 'https://dcamlinhazzmbaldsrdo.supabase.co';
        if (key?.trim()) setupClient(key, url);
        else { setIsAppConfigured(false); setIsLoading(false); }
    }, [setupClient]);

    useEffect(() => {
        if (!supabaseClient) return;
        supabaseClient.auth.getSession().then(({ data: { session } }) => {
            setSession(session);
            setIsLoading(false);
        });
        const { data: { subscription } } = supabaseClient.auth.onAuthStateChange((_event, session) => setSession(session));
        return () => subscription.unsubscribe();
    }, [supabaseClient]);

    const loadData = useCallback(async () => {
        if (!session || isFetching.current) return;
        try {
            isFetching.current = true;
            const data = await fetchAllData();
            setProjects(data.projects || []);
            setMilestones(data.milestones || []);
            setMaintenanceContracts(data.maintenanceContracts || []);
            setIssues(data.issues || []);
            setNotifications(data.notifications || []);
            setUsers(data.users || []);
            if (data.lookups) setLookups(data.lookups);
        } catch (e: any) {
            setErrorMsg("Database Connection Error.");
        } finally {
            isFetching.current = false;
        }
    }, [session]);

    useEffect(() => {
        if (session) loadData();
    }, [session, loadData]);

    const handleAiSearch = async (query: string) => {
        if (!query.trim()) return;
        setIsAnalyzing(true);
        try {
            const res = await analyzeQuery(query, projects, milestones, users, lookups.teams);
            setSearchResult(res);
        } finally {
            setIsAnalyzing(false);
        }
    };

    if (isLoading) return <div className="h-screen w-screen flex items-center justify-center bg-white"><div className="w-12 h-12 border-4 border-violet-600 border-t-transparent rounded-full animate-spin"></div></div>;
    if (!isAppConfigured) return <SystemManagement lookups={lookups} onUpdate={() => {}} language={language} onSaveConfig={(k, u) => { localStorage.setItem('supabaseAnonKey', k); localStorage.setItem('supabaseUrl', u); setupClient(k, u); }} isSetupMode={true} rolePermissions={rolePermissions} onUpdatePermissions={() => {}} />;
    if (!session) return <Login onLoginSuccess={() => loadData()} language={language} setLanguage={setLanguage} supabaseClient={supabaseClient!} />;

    return (
        <div className="flex h-screen bg-slate-50 dark:bg-slate-950 overflow-hidden" dir={language === 'ar' ? 'rtl' : 'ltr'}>
            <Sidebar currentView={view} setCurrentView={setView} language={language} allowedViews={allowedViews} />

            <div className="flex-1 flex flex-col min-w-0">
                <Header 
                    user={currentUser} 
                    language={language} setLanguage={setLanguage} onSearch={handleAiSearch} onLogout={() => supabaseClient?.auth.signOut()} 
                    theme={theme} setTheme={setTheme} isDbConnected={!!session} onToggleSidebar={() => setIsSidebarOpen(!isSidebarOpen)}
                    notifications={notifications} onNotificationRead={loadData}
                />

                {isAnalyzing && <div className="h-1 w-full bg-violet-100 overflow-hidden"><div className="h-full bg-violet-600 animate-[loading_1.5s_infinite]"></div></div>}

                <main className="flex-1 overflow-y-auto p-4 lg:p-8 custom-scrollbar">
                    {view === 'dashboard' && <AnalyticsDashboard projects={projects} milestones={milestones} issues={issues} users={users} projectManagers={lookups.projectManagers} language={language} />}
                    {view === 'projects' && <Projects allProjects={projects} allUsers={users} language={language} onAddProject={async (d) => { await apiAddProject(d); loadData(); }} onOpenEditModal={setEditingProject} onOpenDeleteModal={setDeletingProject} lookups={lookups} isImportModalOpen={isImportModalOpen} onOpenImportModal={() => setIsImportModalOpen(true)} onCloseImportModal={() => setIsImportModalOpen(false)} onImportProjects={async () => {}} />}
                    {view === 'milestones' && <Milestones allMilestones={milestones} allProjects={projects} language={language} onAddMilestones={async (d) => { await apiAddMilestones(d); loadData(); }} onOpenEditModal={setEditingMilestone} onViewMilestoneDetails={setViewingMilestone} onUpdateMilestone={async (id, d) => { await apiUpdateMilestone(id, d); loadData(); }} lookups={lookups} />}
                    {view === 'team' && <Team allUsers={users} allProjects={projects} language={language} />}
                    {view === 'payments' && <Payments allProjects={projects} allMilestones={milestones} allTeams={lookups.teams} language={language} onUpdateMilestone={async (id, d) => { await apiUpdateMilestone(id, d); loadData(); }} />}
                    {view === 'maintenanceContracts' && <MaintenanceContracts contracts={maintenanceContracts} customers={lookups.customers} language={language} onAddContract={async (d) => { await apiAddContract(d); loadData(); }} onUpdateContract={async (id, d) => { await apiUpdateContract(id, d); loadData(); }} />}
                    {view === 'issues' && <Issues allIssues={issues} allProjects={projects} allMilestones={milestones} allUsers={users} language={language} onAddIssue={async (d) => { await apiAddIssue(d); loadData(); }} onUpdateIssue={async (id, d) => { await apiUpdateIssue(id, d); loadData(); }} onAddComment={async (id, uid, c) => { await apiAddIssueComment(id, uid, c); loadData(); }} currentUser={currentUser} />}
                    {view === 'system' && <SystemManagement lookups={lookups} onUpdate={apiUpdateLookups} language={language} onSaveConfig={(k, u) => { localStorage.setItem('supabaseAnonKey', k); localStorage.setItem('supabaseUrl', u); setupClient(k, u); }} rolePermissions={rolePermissions} onUpdatePermissions={(p) => { setRolePermissions(p); localStorage.setItem('rolePermissions', JSON.stringify(p)); }} />}
                    {view === 'filter' && <MilestoneFilter projects={projects} milestones={milestones} teams={lookups.teams} customers={lookups.customers} projectManagers={lookups.projectManagers} language={language} onUpdateMilestone={async (id, d) => { await apiUpdateMilestone(id, d); loadData(); }} />}
                    {view === 'reports' && <ReportsBuilder projects={projects} milestones={milestones} issues={issues} teams={lookups.teams} language={language} />}
                </main>
            </div>

            {editingProject && <EditProjectModal projectToEdit={editingProject} lookups={lookups} onClose={() => setEditingProject(null)} onUpdateProject={async (id, d) => { await apiUpdateProject(id, d); loadData(); }} language={language} />}
            {editingMilestone && <EditMilestoneModal milestoneToEdit={editingMilestone} allMilestones={milestones} teams={lookups.teams} projects={projects} allMilestoneUpdates={[]} allUsers={users} currentUser={currentUser} onClose={() => setEditingMilestone(null)} onUpdateMilestone={async (id, d) => { await apiUpdateMilestone(id, d); loadData(); }} onAddMilestones={async (d) => { await apiAddMilestones(d); loadData(); }} onAddUpdate={async () => {}} language={language} />}
            {viewingMilestone && <MilestoneDetailModal milestone={viewingMilestone} projects={projects} allMilestoneUpdates={[]} allUsers={users} lookups={lookups} onClose={() => setViewingMilestone(null)} language={language} />}
            {deletingProject && <ConfirmDeleteModal project={deletingProject} onClose={() => setDeletingProject(null)} onConfirm={async () => { await apiDeleteProject(deletingProject.id); setDeletingProject(null); loadData(); }} language={language} />}
            {searchResult && <SearchResultModal result={searchResult} onClose={() => setSearchResult(null)} language={language} />}

            <Chatbot isOpen={isChatbotOpen} onClose={() => setIsChatbotOpen(false)} language={language} projects={projects} milestones={milestones} users={users} lookups={lookups} />
            <button onClick={() => setIsChatbotOpen(true)} className="fixed bottom-6 right-6 bg-violet-600 text-white p-4 rounded-full shadow-2xl hover:scale-110 active:scale-95 transition-all z-40"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" viewBox="0 0 20 20" fill="currentColor"><path d="M2 5a2 2 0 012-2h7a2 2 0 012 2v4a2 2 0 01-2 2H9l-3 3v-3H4a2 2 0 01-2-2V5z" /></svg></button>
            <style>{`@keyframes loading { 0% { transform: translateX(-100%); } 100% { transform: translateX(100%); } }`}</style>
        </div>
    );
};

export default App;

