    ar: { dashboard: 'الرئيسية', filter: 'الفلترة', projects: 'المشاريع', milestones: 'المعالم', team: 'المدراء', payments: 'المالية', maintenanceContracts: 'الصيانة', issues: 'الأعطال', system: 'الإعدادات', reports: 'التقارير' },
