  };
  const t = translations[language];

  return (
    <aside className="w-20 lg:w-64 flex-shrink-0 m-4 flex flex-col h-[calc(100vh-2rem)]" dir={language === 'ar' ? 'rtl' : 'ltr'}>
      <div className="glass-panel rounded-[2.5rem] flex-1 flex flex-col shadow-2xl overflow-hidden">
