import React, { useState, useEffect } from 'react';
import { Lookups, Language, Lookup, RolePermissions, View, User } from '../types';
import LookupEditor from './LookupEditor';
import { getSupabase } from '../services/supabaseClient';

interface SystemManagementProps {
    lookups: Lookups;
    onUpdate: (lookupType: keyof Lookups, newLookups: Lookup[]) => void;
    language: Language;
    onSaveConfig: (supabaseKey: string, supabaseUrl: string) => void;
    isSetupMode?: boolean;
    rolePermissions: RolePermissions[];
    onUpdatePermissions: (newPermissions: RolePermissions[]) => void;
}

const SystemManagement: React.FC<SystemManagementProps> = ({ lookups, onUpdate, language, onSaveConfig, isSetupMode = false, rolePermissions, onUpdatePermissions }) => {
    const [supabaseKey, setSupabaseKey] = useState('');
    const [supabaseUrl, setSupabaseUrl] = useState('https://dcamlinhazzmbaldsrdo.supabase.co');
    const [activeTab, setActiveTab] = useState<'users' | 'permissions' | 'lookups' | 'config'>('users');
    const [dbUsers, setDbUsers] = useState<User[]>([]);
    const [isLoadingUsers, setIsLoadingUsers] = useState(false);

    useEffect(() => {
        if (!isSetupMode) {
            setSupabaseKey(localStorage.getItem('supabaseAnonKey') || '');
            setSupabaseUrl(localStorage.getItem('supabaseUrl') || 'https://dcamlinhazzmbaldsrdo.supabase.co');
            fetchUsersFromDb();
        }
    }, [isSetupMode]);

    const fetchUsersFromDb = async () => {
        const sb = getSupabase();
        if (!sb) return;
        setIsLoadingUsers(true);
        const { data } = await sb.from('users').select('*').order('name');
        if (data) setDbUsers(data.map(u => ({ id: u.id, name: u.name, type: u.type, avatarUrl: u.avatar_url })));
        setIsLoadingUsers(false);
    };

    const handleRoleChange = async (userId: string, newRole: string) => {
        const sb = getSupabase();
        if (!sb) return;
        const { error } = await sb.from('users').update({ type: newRole }).eq('id', userId);
        if (!error) fetchUsersFromDb();
    };

    const translations = {
        ar: {
            title: "إدارة النظام", subtitle: "التحكم الكامل في المستخدمين، الصلاحيات، وجداول البيانات.",
            users: "الموظفين", permissions: "الصلاحيات", lookups: "جداول البحث", config: "الإعدادات",
            userName: "اسم الموظف", userRole: "الدور الوظيفي", actions: "إجراءات", 
            save: "حفظ التغييرات", refresh: "تحديث القائمة"
        },
        en: {
            title: "Control Center", subtitle: "Total management of users, roles, and system data.",
            users: "User Management", permissions: "Access Matrix", lookups: "Lookup Tables", config: "Connection",
            userName: "Employee Name", userRole: "System Role", actions: "Actions",
            save: "Save Changes", refresh: "Refresh List"
        }
    };
    const t = translations[language];

    const allAvailableViews: {id: View, label: string}[] = [
        { id: 'dashboard', label: language === 'ar' ? 'الرئيسية' : 'Dashboard' },
        { id: 'projects', label: language === 'ar' ? 'المشاريع' : 'Projects' },
        { id: 'milestones', label: language === 'ar' ? 'المعالم' : 'Milestones' },
        { id: 'issues', label: language === 'ar' ? 'الأعطال' : 'Issues' },
        { id: 'team', label: language === 'ar' ? 'فريق العمل' : 'Management' },
        { id: 'payments', label: language === 'ar' ? 'المالية' : 'Finance' },
        { id: 'reports', label: language === 'ar' ? 'التقارير' : 'Reports' },
        { id: 'maintenanceContracts', label: language === 'ar' ? 'الصيانة' : 'Maintenance' },
        { id: 'filter', label: language === 'ar' ? 'الفلترة' : 'Filter' },
        { id: 'system', label: language === 'ar' ? 'الإعدادات' : 'System' },
    ];

    const togglePermission = (role: string, view: View) => {
        const newPermissions = rolePermissions.map(rp => {
            if (rp.role === role) {
                const alreadyAllowed = rp.allowedViews.includes(view);
                return { ...rp, allowedViews: alreadyAllowed ? rp.allowedViews.filter(v => v !== view) : [...rp.allowedViews, view] };
            }
            return rp;
        });
        onUpdatePermissions(newPermissions);
    };

    return (
        <div className="max-w-7xl mx-auto space-y-10 pb-24">
            <div className="flex flex-col md:flex-row justify-between items-end gap-6">
                <div>
                    <h1 className="text-4xl font-black text-white uppercase tracking-tight">{t.title}</h1>
                    <p className="text-slate-500 font-bold text-xs mt-2 uppercase tracking-[0.3em]">{t.subtitle}</p>
                </div>
                {!isSetupMode && (
                    <div className="glass-panel p-1.5 rounded-2xl flex gap-1">
                        {['users', 'permissions', 'lookups', 'config'].map((tab) => (
                            <button 
                                key={tab}
                                onClick={() => setActiveTab(tab as any)}
                                className={`px-6 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === tab ? 'bg-violet-600 text-white shadow-xl' : 'text-slate-400 hover:text-white'}`}
                            >
                                {t[tab as keyof typeof t]}
                            </button>
                        ))}
                    </div>
                )}
            </div>

            {activeTab === 'users' && !isSetupMode && (
                <div className="glass-panel rounded-[2.5rem] overflow-hidden shadow-2xl animate-in fade-in duration-500">
                    <div className="p-8 border-b border-white/5 flex justify-between items-center">
                        <h2 className="text-sm font-black text-white uppercase tracking-widest">{t.users}</h2>
                        <button onClick={fetchUsersFromDb} className="p-2 hover:bg-white/5 rounded-full transition-colors text-slate-400">
                            <svg className={`w-5 h-5 ${isLoadingUsers ? 'animate-spin' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"/></svg>
                        </button>
                    </div>
                    <div className="overflow-x-auto">
                        <table className="w-full text-start">
                            <thead>
                                <tr className="bg-white/5">
                                    <th className="px-8 py-5 text-[10px] font-black text-slate-500 uppercase tracking-widest text-start">{t.userName}</th>
                                    <th className="px-8 py-5 text-[10px] font-black text-slate-500 uppercase tracking-widest text-start">{t.userRole}</th>
                                    <th className="px-8 py-5 text-[10px] font-black text-slate-500 uppercase tracking-widest text-end">{t.actions}</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-white/5">
                                {dbUsers.map(u => (
                                    <tr key={u.id} className="hover:bg-white/[0.02] transition-colors">
                                        <td className="px-8 py-5 flex items-center gap-4">
                                            <img src={u.avatarUrl || `https://ui-avatars.com/api/?name=${u.name}&background=8b5cf6&color=fff`} className="w-10 h-10 rounded-2xl shadow-lg border border-white/10" />
                                            <div>
                                                <p className="text-sm font-bold text-white">{u.name}</p>
                                                <p className="text-[10px] font-medium text-slate-500 uppercase tracking-tighter">UID: {u.id.substring(0,8)}</p>
                                            </div>
                                        </td>
                                        <td className="px-8 py-5">
                                            <select 
                                                value={u.type || 'Staff'} 
                                                onChange={(e) => handleRoleChange(u.id, e.target.value)}
                                                className="bg-slate-900 border border-white/10 rounded-xl px-4 py-2 text-[10px] font-black text-violet-400 uppercase tracking-widest outline-none focus:ring-1 focus:ring-violet-500"
                                            >
                                                <option value="PM">Project Manager (PM)</option>
                                                <option value="PS">Pro Services (PS)</option>
                                                <option value="Staff">Internal Staff</option>
                                                <option value="Client">Client Account</option>
                                            </select>
                                        </td>
                                        <td className="px-8 py-5 text-end">
                                            <button className="text-red-500 text-[10px] font-black uppercase tracking-widest hover:underline px-3 py-1">Revoke</button>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </div>
            )}

            {activeTab === 'permissions' && (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-8 animate-in slide-in-from-bottom-6 duration-500">
                    {rolePermissions.map(rolePerm => (
                        <div key={rolePerm.role} className="glass-panel p-8 rounded-[3rem] shadow-xl border border-white/5 relative overflow-hidden group">
                            <div className="absolute -top-10 -right-10 w-40 h-40 bg-violet-600/5 rounded-full blur-3xl group-hover:bg-violet-600/10 transition-all"></div>
                            <div className="flex items-center gap-5 mb-10">
                                <div className="w-14 h-14 bg-violet-600 rounded-3xl flex items-center justify-center text-white shadow-2xl shadow-violet-600/30">
                                    <span className="text-lg font-black">{rolePerm.role}</span>
                                </div>
                                <div>
                                    <h3 className="text-xl font-black text-white uppercase tracking-tight">{rolePerm.role} Profile</h3>
                                    <p className="text-[10px] text-slate-500 font-bold uppercase tracking-[0.2em]">{rolePerm.allowedViews.length} modules active</p>
                                </div>
                            </div>
                            <div className="grid grid-cols-2 gap-3">
                                {allAvailableViews.map(viewDef => {
                                    const allowed = rolePerm.allowedViews.includes(viewDef.id);
                                    return (
                                        <button 
                                            key={viewDef.id} 
                                            onClick={() => togglePermission(rolePerm.role, viewDef.id)}
                                            className={`flex items-center gap-3 p-4 rounded-2xl border transition-all ${allowed ? 'bg-violet-600/20 border-violet-600 text-white shadow-inner' : 'bg-white/5 border-white/5 text-slate-500 hover:border-white/10'}`}
                                        >
                                            <div className={`w-2.5 h-2.5 rounded-full ${allowed ? 'bg-violet-500 animate-pulse' : 'bg-slate-700'}`}></div>
                                            <span className="text-[10px] font-black uppercase tracking-widest">{viewDef.label}</span>
                                        </button>
                                    );
                                })}
                            </div>
                        </div>
                    ))}
                </div>
            )}

            {activeTab === 'lookups' && (
                <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-8">
                    <LookupEditor title="Countries" initialValues={lookups.countries} onSave={(v) => onUpdate('countries', v as Lookup[])} language={language} />
                    <LookupEditor title="Categories" initialValues={lookups.categories} onSave={(v) => onUpdate('categories', v as Lookup[])} language={language} />
                    <LookupEditor title="Teams" initialValues={lookups.teams} onSave={(v) => onUpdate('teams', v as Lookup[])} language={language} />
                </div>
            )}

            {activeTab === 'config' && (
                <div className="glass-panel p-10 rounded-[3rem] max-w-2xl mx-auto border border-white/5 shadow-2xl">
                    <h2 className="text-2xl font-black text-white uppercase mb-10 tracking-tight">Database Config</h2>
                    <div className="space-y-8">
                        <div>
                            <label className="block text-[10px] font-black text-slate-500 uppercase tracking-widest mb-3 ps-1">Supabase URL</label>
                            <input type="text" value={supabaseUrl} onChange={e => setSupabaseUrl(e.target.value)} className="w-full bg-black/40 border border-white/10 rounded-2xl p-5 text-sm font-bold text-white outline-none focus:ring-2 focus:ring-violet-600 transition-all" />
