                        </div>
                        <button onClick={() => onSaveConfig(supabaseKey, supabaseUrl)} className="w-full py-5 bg-violet-600 text-white rounded-2xl text-xs font-black uppercase tracking-[0.3em] hover:bg-violet-700 transition-all shadow-xl shadow-violet-600/20">{t.save}</button>
                    </div>
                </div>
            )}
        </div>
    );
};

