                                    <img src={u.avatarUrl || `https://ui-avatars.com/api/?name=${u.name}&background=8b5cf6&color=fff`} className="w-10 h-10 rounded-2xl shadow-xl" />
                                    <div>
                                        <p className="text-sm font-black text-white">{u.name}</p>
                                        <p className="text-[9px] font-black text-violet-400 uppercase tracking-widest">{u.type}</p>
                                    </div>
                                </div>
                                <div className="text-end">
                                    <span className="text-xl font-black text-white">{(Math.random() * 100).toFixed(0)}%</span>
                                    <p className="text-[8px] font-black text-slate-500 uppercase">Efficiency</p>
                                </div>
                            </div>
                        ))}
                    </div>
                </WidgetFrame>
            </div>
        </div>
    );
};

